INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C1','kor',4,1,'u5',2,'이 단원에서 배울 것 — 말로는 자신 있게 발표하기, 글로는 독서 감상문 쓰기 — 말과 글로 생각을 전함',ARRAY['[4국01-05]·[4국05-03](차시 머리 표기 — 단원 도입)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C2','kor',4,1,'u5',2,'떨림을 이겨 내는 길 — 발표할 내용을 미리 찾아 정리하고 연습함 — 생각하지 않거나 남에게 넘기는 것은 길이 아님',ARRAY['[4국01-05]·[4국05-03](차시 머리 표기 — 단원 도입)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C3','kor',4,1,'u5',2,'인상 깊은 장면 — 내 마음이 움직인 자리(공감 · 인물의 마음 · 떠오른 질문 · 얻은 교훈) — 글자 수나 길이로 고르지 않음',ARRAY['[4국01-05]·[4국05-03](차시 머리 표기 — 단원 도입)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C4','kor',4,1,'u5',2,'한 문장으로 책 소개하기 — 책이 준 느낌이나 생각을 한 문장에 담음 — 쪽수 · 색깔 같은 겉모습이 아님',ARRAY['[4국01-05]·[4국05-03](차시 머리 표기 — 단원 도입)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C5','kor',4,1,'u5',2,'이야기 속 낱말 — 발표(알아낸 것을 여러 사람 앞에 알림) · 조사(자세히 살펴봄) · 긴장(마음을 조이고 정신을 바짝 차림)',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 자신 있게 발표하는 방법 알기)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C6','kor',4,1,'u5',2,'자신감은 준비에서 — 하람이는 날마다 조금씩 알아보며 긴장을 잊었고, 한 문장을 떼자 목소리가 커졌음 — 타고나는 것이 아님',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 자신 있게 발표하는 방법 알기)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C7','kor',4,1,'u5',2,'인물에게 묻기 — 인물이 겪은 과정과 마음을 묻는 질문을 함 — 이야기와 상관없는 생김새 · 물건은 묻지 않음',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 자신 있게 발표하는 방법 알기)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C8','kor',4,1,'u5',2,'자신 있게 발표하는 방법 — 미리 찾아 정리하기 · 알맞은 목소리 크기로 또박또박 · 알맞은 빠르기 · 듣는 사람 바라보기',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 자신 있게 발표하는 방법 알기)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C9','kor',4,1,'u5',2,'큰 목소리의 까닭 — 목소리를 크게 하는 까닭은 잘 들리게 하려는 것 — 무조건 소리치면 오히려 듣기 힘듦',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 자신 있게 발표하는 방법 알기)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C10','kor',4,1,'u5',2,'알맞은 빠르기 — 너무 빠르면 알아듣기 어려움 — 한 문장씩 끊어 알맞은 빠르기로 말함',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 자신 있게 발표하는 방법 알기)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C11','kor',4,1,'u5',2,'아쉬운 점과 고칠 방법 — 무엇이 아쉬웠는지에 맞는 고칠 방법을 찾음(못 들음 → 목소리 크기 · 종이만 봄 → 바라보기)',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 자신 있게 발표하는 방법 알기)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C12','kor',4,1,'u5',4,'주제에 맞는 조사 항목 — 주제를 소개하는 데 필요한 것만 정함(생김새 · 먹이 · 사는 곳 · 줄어든 까닭) — 이름 글자 수 · 내 취향 ✗',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 친구들 앞에서 자신 있게 발표하기)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
