INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u5-C14','kor',4,1,'u5',4,'믿을 만한 자료 — 누가 만들었는지 분명한 곳의 자료 — 출처 모를 댓글 · 들은 이야기 ✗',ARRAY['[4국01-05]·[4국01-03](차시 머리 표기 — 친구들 앞에서 자신 있게 발표하기)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
