INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X02','kor',4,'u5',ARRAY['K4-1-u5-C2']::text[],'발표가 떨리면 생각하지 않거나 남에게 넘기면 된다고 여긴다','미리 준비하고 연습해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X03','kor',4,'u5',ARRAY['K4-1-u5-C3']::text[],'인상 깊은 장면을 글자 수가 많거나 맨 앞 · 맨 뒤라는 까닭으로 고른다','마음이 움직인 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X04','kor',4,'u5',ARRAY['K4-1-u5-C4']::text[],'책을 한 문장으로 소개하면서 쪽수 · 색깔 같은 겉모습만 말한다','책이 준 느낌을 담아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X05','kor',4,'u5',ARRAY['K4-1-u5-C5']::text[],'발표 · 조사 · 긴장의 뜻을 엇갈리게 안다','문장 속에서 뜻을 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X06','kor',4,'u5',ARRAY['K4-1-u5-C6']::text[],'자신감은 타고나거나 목소리가 크면 저절로 생긴다고 여긴다','준비와 연습에서 나와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X07','kor',4,'u5',ARRAY['K4-1-u5-C7']::text[],'인물에게 묻는 질문으로 이야기와 상관없는 생김새 · 물건을 묻는다','겪은 과정과 마음을 물어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X08','kor',4,'u5',ARRAY['K4-1-u5-C8']::text[],'종이만 내려다보며 읽거나 내용만 늘이는 것을 자신 있게 발표하는 방법으로 여긴다','정리 · 크기 · 빠르기 · 눈길') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X09','kor',4,'u5',ARRAY['K4-1-u5-C9']::text[],'무조건 가장 큰 소리로 소리쳐야 자신 있게 말하는 것이라고 여긴다','잘 들리게 하려는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X10','kor',4,'u5',ARRAY['K4-1-u5-C10']::text[],'빨리 말할수록 잘한 발표라고 여기거나 빠르기는 상관없다고 여긴다','알맞은 빠르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X11','kor',4,'u5',ARRAY['K4-1-u5-C11']::text[],'아쉬운 점에 맞지 않는 고칠 방법을 고른다','무엇이 아쉬웠나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X12','kor',4,'u5',ARRAY['K4-1-u5-C12']::text[],'주제를 소개하는 데 필요 없는 것(이름 글자 수 · 내 취향)을 조사 항목으로 고른다','주제와 이어지나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X13','kor',4,'u5',ARRAY['K4-1-u5-C13','K4-1-u5-C14']::text[],'누가 썼는지 모르는 댓글 · 들은 이야기 · 짐작한 내용을 발표 자료로 쓴다','누가 만들었나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X14','kor',4,'u5',ARRAY['K4-1-u5-C15']::text[],'가져온 자료의 출처를 밝히지 않거나 내가 알아낸 것처럼 말한다','어디서 가져왔나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X15','kor',4,'u5',ARRAY['K4-1-u5-C16']::text[],'찾은 내용을 알맞지 않은 조사 항목에 엇갈리게 정리한다','항목마다 맞는 내용') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X16','kor',4,'u5',ARRAY['K4-1-u5-C17']::text[],'시작하는 말 · 설명하는 말 · 끝맺는 말에 들어갈 내용을 엇갈리게 놓는다','시작 · 설명 · 끝맺음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X17','kor',4,'u5',ARRAY['K4-1-u5-C18']::text[],'어려운 말을 자료에 나온 그대로 옮겨야 바른 발표라고 여긴다','이해한 뒤 쉬운 말로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X18','kor',4,'u5',ARRAY['K4-1-u5-C19']::text[],'발표할 때 자료를 그대로 읽기만 하거나 보여 주는 자료를 가리키지 않는다','가리키고 눈 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X19','kor',4,'u5',ARRAY['K4-1-u5-C20','K4-1-u5-C47']::text[],'듣는 사람은 발표와 상관없다고 여겨 딴짓을 하거나 발표 도중에 끼어들어 묻는다','듣는 사람도 참여해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X20','kor',4,'u5',ARRAY['K4-1-u5-C20','K4-1-u5-C42']::text[],'칭찬을 「잘했어」처럼 막연하게만 하거나 못한 점만 짚는다','잘한 점을 구체적으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X21','kor',4,'u5',ARRAY['K4-1-u5-C21']::text[],'발표를 목소리 크기나 길이 하나로만 되돌아본다','여러 기준으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X22','kor',4,'u5',ARRAY['K4-1-u5-C22']::text[],'독서 감상문을 책의 줄거리를 옮겨 적은 글로 여긴다','생각이나 느낌을 쓴 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X23','kor',4,'u5',ARRAY['K4-1-u5-C23']::text[],'독서 감상문을 쓰는 까닭을 책을 빨리 읽거나 내기만 하려는 것으로 여긴다','나누고 오래 기억해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X24','kor',4,'u5',ARRAY['K4-1-u5-C24']::text[],'독서 감상문에 들어갈 내용이 아닌 것(쪽수 · 책값)을 들어갈 내용으로 고른다','제목부터 생각이나 느낌까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X25','kor',4,'u5',ARRAY['K4-1-u5-C25','K4-1-u5-C37']::text[],'감상문 제목은 책 제목을 그대로 써야만 한다고 여기거나 제목을 빼먹는다','주제나 느낌이 드러나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X26','kor',4,'u5',ARRAY['K4-1-u5-C26']::text[],'읽은 까닭 자리에 쪽수 · 읽은 시간 같은 상관없는 사실을 쓴다','언제 · 어디서 · 왜') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X27','kor',4,'u5',ARRAY['K4-1-u5-C27']::text[],'있었던 일(책의 내용)과 생각이나 느낌을 가르지 못해 서로 바꾸어 쓴다','책 이야기와 내 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X28','kor',4,'u5',ARRAY['K4-1-u5-C28']::text[],'인상 깊은 장면만 쓰고 그 장면이 기억에 남은 까닭을 빼먹는다','까닭과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X29','kor',4,'u5',ARRAY['K4-1-u5-C29']::text[],'생각이나 느낌을 「재미있었다」 한마디로 끝낸다','깨달은 점 · 다짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X30','kor',4,'u5',ARRAY['K4-1-u5-C30']::text[],'줄거리만 있거나 느낌만 있어도 독서 감상문이 된다고 여긴다','둘이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X31','kor',4,'u5',ARRAY['K4-1-u5-C31','K4-1-u5-C37']::text[],'책의 모든 장면을 빠짐없이 적어야 좋은 감상문이라고 여긴다','줄거리는 간추려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X32','kor',4,'u5',ARRAY['K4-1-u5-C32']::text[],'감상문의 한 부분이 책 이야기인지 내 마음인지 거꾸로 가른다','먼저 갈라 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X33','kor',4,'u5',ARRAY['K4-1-u5-C33']::text[],'가장 얇아 빨리 읽을 수 있는 책이나 아무 책이나 고르는 것을 좋은 방법으로 여긴다','읽고 싶어지는 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X34','kor',4,'u5',ARRAY['K4-1-u5-C34']::text[],'쓸 내용을 정리할 때 항목과 내용을 엇갈리게 잇거나 정리할 필요가 없다고 여긴다','항목에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X35','kor',4,'u5',ARRAY['K4-1-u5-C35']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 엇갈리게 놓는다(다짐으로 시작하기 등)','까닭 → 내용 · 장면 → 느낌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X36','kor',4,'u5',ARRAY['K4-1-u5-C36']::text[],'문단을 줄 수 · 쉼표에 맞추어 나누거나 아예 나누지 않는다','내용이 바뀌는 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X37','kor',4,'u5',ARRAY['K4-1-u5-C38']::text[],'고쳐 쓸 때 빠진 것을 덧붙이지 않고 문장을 지우거나 늘이거나 표시만 바꾼다','빠진 것을 덧붙여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X38','kor',4,'u5',ARRAY['K4-1-u5-C39']::text[],'독서 감상문은 정해진 한 가지 형식으로만 써야 한다고 여긴다','편지 · 일기 · 만화 · 인터뷰') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X39','kor',4,'u5',ARRAY['K4-1-u5-C40']::text[],'같은 책을 읽으면 모두 같은 장면이 인상 깊어야 하고, 나와 다르면 틀렸다고 여긴다','저마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X40','kor',4,'u5',ARRAY['K4-1-u5-C41']::text[],'가 본 곳을 소개하며 듣는 사람에게 필요 없는 내용(옷값 · 출발 시각)을 넣는다','위치 · 볼거리 · 인상 깊은 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X41','kor',4,'u5',ARRAY['K4-1-u5-C42']::text[],'솔직하다며 친구의 글을 비난하는 댓글을 쓴다','칭찬과 격려') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X42','kor',4,'u5',ARRAY['K4-1-u5-C43']::text[],'친구가 감상문에 쓴 내용과 상관없는 댓글을 쓴다','친구 글을 먼저 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X43','kor',4,'u5',ARRAY['K4-1-u5-C44']::text[],'발표는 잘하는 친구에게만 맡기는 것을 실천으로 여긴다','모두 해 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X44','kor',4,'u5',ARRAY['K4-1-u5-C45']::text[],'1분 말하기에서 뽑은 주제를 벗어나거나 같은 말을 되풀이한다','주제에 맞게 차례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X45','kor',4,'u5',ARRAY['K4-1-u5-C47']::text[],'발표를 들으며 중요한 내용을 적는 것을 딴짓으로 여긴다','적으며 들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X46','kor',4,'u5',ARRAY['K4-1-u5-C48']::text[],'순우리말의 뜻을 엇갈려 엉뚱한 자리에 쓴다(비가 도란도란)','뜻을 넣어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X47','kor',4,'u5',ARRAY['K4-1-u5-C48']::text[],'순우리말은 옛날에만 쓰던 말이라 지금은 쓰지 않는다고 여긴다','지금도 쓰는 고운 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X48','kor',4,'u5',ARRAY['K4-1-u5-C49']::text[],'ㅅ · ㅆ을 놓이는 자리와 상관없이 늘 같은 모양 · 크기로 쓴다','자리에 맞추어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u5-X49','kor',4,'u5',ARRAY['K4-1-u5-C46']::text[],'말로 전하기나 글로 전하기 가운데 하나만 중요하거나, 내 생각만 전하면 된다고 여긴다','말과 글 · 귀 기울이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#1','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C1',1,'mc','auto','「말과 글로 전하는 생각」 단원에서 배우는 두 가지를 바르게 고른 것은 무엇인가요?',ARRAY['K4-1-u5-X01']::text[],false,'{"seq":1,"concept":"K4-1-u5-C1","difficulty":1,"kind":"mc","stem":"「말과 글로 전하는 생각」 단원에서 배우는 두 가지를 바르게 고른 것은 무엇인가요?","options":[{"t":"자신 있게 발표하기와 독서 감상문 쓰기","correct":true},{"t":"어림하여 계산하기와 그래프 그리기","mis":"K4-1-u5-X01"},{"t":"노래 부르기와 그림 그리기","mis":"K4-1-u5-X01"},{"t":"받아쓰기와 낱말 외우기","mis":"K4-1-u5-X01"}],"explanation":["말로 전하기","글로 전하기","발표와 감상문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#2','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C5',1,'mc','auto','「목소리를 찾은 날」에 나온 낱말 「긴장」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X05']::text[],false,'{"seq":2,"concept":"K4-1-u5-C5","difficulty":1,"kind":"mc","stem":"「목소리를 찾은 날」에 나온 낱말 「긴장」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"마음을 조이고 정신을 바짝 차림","correct":true},{"t":"알아낸 것을 여러 사람 앞에 알림","mis":"K4-1-u5-X05"},{"t":"내용을 알기 위해 자세히 살펴봄","mis":"K4-1-u5-X05"},{"t":"마음을 놓고 편히 쉼","mis":"K4-1-u5-X05"}],"explanation":["발표를 앞둔 마음","조이는 마음","긴장이에요."],"asset":{"type":"passage","lines":["하람이는 친구들 앞에서 말하는 일이 가장 무서웠다.","발표 숙제를 받자 종이를 접어 가방 깊숙이 넣었다.","하람이는 여름밤마다 보던 북두칠성을 발표하기로 했다.","별자리 책을 찾고, 할머니께 여쭙고, 사진도 확인했다.","날마다 조금씩 알아보는 동안 긴장한 것도 잊었다.","발표 날, 한 문장을 떼자 목소리가 조금씩 커졌다."],"title":"목소리를 찾은 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#3','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C2',1,'mc','auto','발표만 하려고 하면 떨리는 마음을 이겨 내려면 무엇을 해야 하나요?',ARRAY['K4-1-u5-X02']::text[],false,'{"seq":3,"concept":"K4-1-u5-C2","difficulty":1,"kind":"mc","stem":"발표만 하려고 하면 떨리는 마음을 이겨 내려면 무엇을 해야 하나요?","options":[{"t":"발표할 내용을 미리 찾아 정리하고 연습한다","correct":true},{"t":"발표 순서가 오기 전까지 생각하지 않는다","mis":"K4-1-u5-X02"},{"t":"발표를 다른 사람에게 넘긴다","mis":"K4-1-u5-X02"},{"t":"발표 날 아침에 처음으로 내용을 정한다","mis":"K4-1-u5-X02"}],"explanation":["떨림을 줄이는 것은?","미리 준비하기","연습이 자신감을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#4','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C8',1,'mc','auto','자신 있게 발표하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X08','K4-1-u5-X10','K4-1-u5-X09']::text[],false,'{"seq":4,"concept":"K4-1-u5-C8","difficulty":1,"kind":"mc","stem":"자신 있게 발표하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"듣는 사람을 바라보며 말한다","correct":true},{"t":"종이에 쓴 것만 내려다보며 읽는다","mis":"K4-1-u5-X08"},{"t":"빨리 끝내려고 서둘러 말한다","mis":"K4-1-u5-X10"},{"t":"무조건 가장 큰 소리로 소리친다","mis":"K4-1-u5-X09"}],"explanation":["누구에게 말하나요?","듣는 사람","바라보며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#5','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C3',2,'mc','auto','책에서 인상 깊은 장면으로 고르기에 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X03']::text[],false,'{"seq":5,"concept":"K4-1-u5-C3","difficulty":2,"kind":"mc","stem":"책에서 인상 깊은 장면으로 고르기에 알맞지 않은 것은 무엇인가요?","options":[{"t":"글자 수가 가장 많은 장면","correct":true},{"t":"내 경험과 비슷해 공감할 수 있는 장면","mis":"K4-1-u5-X03"},{"t":"인물의 마음이 잘 드러난 장면","mis":"K4-1-u5-X03"},{"t":"질문이 많이 떠오르는 장면","mis":"K4-1-u5-X03"}],"explanation":["마음이 움직였나요?","글자 수는 상관없어요.","글자 수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#6','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C6',2,'mc','auto','「목소리를 찾은 날」에서 하람이의 목소리가 발표 날 조금씩 커진 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X06','K4-1-u5-X02']::text[],false,'{"seq":6,"concept":"K4-1-u5-C6","difficulty":2,"kind":"mc","stem":"「목소리를 찾은 날」에서 하람이의 목소리가 발표 날 조금씩 커진 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"날마다 조금씩 알아보며 발표를 준비했기 때문이다","correct":true},{"t":"원래부터 목소리가 커서 떨지 않았기 때문이다","mis":"K4-1-u5-X06"},{"t":"선생님께서 대신 말해 주셨기 때문이다","mis":"K4-1-u5-X02"},{"t":"발표를 다른 친구에게 넘겼기 때문이다","mis":"K4-1-u5-X02"}],"explanation":["하람이가 한 일은?","책 · 할머니 · 사진","준비가 힘이 되었어요."],"asset":{"type":"passage","lines":["하람이는 친구들 앞에서 말하는 일이 가장 무서웠다.","발표 숙제를 받자 종이를 접어 가방 깊숙이 넣었다.","하람이는 여름밤마다 보던 북두칠성을 발표하기로 했다.","별자리 책을 찾고, 할머니께 여쭙고, 사진도 확인했다.","날마다 조금씩 알아보는 동안 긴장한 것도 잊었다.","발표 날, 한 문장을 떼자 목소리가 조금씩 커졌다."],"title":"목소리를 찾은 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#7','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C7',2,'mc','auto','하람이에게 물어볼 질문으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X07']::text[],false,'{"seq":7,"concept":"K4-1-u5-C7","difficulty":2,"kind":"mc","stem":"하람이에게 물어볼 질문으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"「가방은 무슨 색이었나요?」","correct":true},{"t":"「북두칠성을 어떻게 조사했나요?」","mis":"K4-1-u5-X07"},{"t":"「종이를 가방에 넣었을 때 마음은 어땠나요?」","mis":"K4-1-u5-X07"},{"t":"「한 문장을 떼고 나서 어떤 마음이 들었나요?」","mis":"K4-1-u5-X07"}],"explanation":["하람이가 겪은 일과 마음","가방 색은?","이야기와 상관없어요."],"asset":{"type":"passage","lines":["하람이는 친구들 앞에서 말하는 일이 가장 무서웠다.","발표 숙제를 받자 종이를 접어 가방 깊숙이 넣었다.","하람이는 여름밤마다 보던 북두칠성을 발표하기로 했다.","별자리 책을 찾고, 할머니께 여쭙고, 사진도 확인했다.","날마다 조금씩 알아보는 동안 긴장한 것도 잊었다.","발표 날, 한 문장을 떼자 목소리가 조금씩 커졌다."],"title":"목소리를 찾은 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#8','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C9',2,'ox','auto','무조건 가장 큰 소리로 소리쳐야 자신 있게 발표한 것이에요.',ARRAY['K4-1-u5-X09']::text[],false,'{"seq":8,"concept":"K4-1-u5-C9","difficulty":2,"kind":"ox","stem":"무조건 가장 큰 소리로 소리쳐야 자신 있게 발표한 것이에요.","answer":"X","reason_options":[{"t":"목소리를 크게 하는 까닭은 잘 들리게 하려는 것이라 교실 뒤까지 편하게 들릴 만큼이면 되기 때문에","correct":true},{"t":"소리가 클수록 자신감이 크게 드러나기 때문에","mis":"K4-1-u5-X09"}],"mis":"K4-1-u5-X09","explanation":["크게 하는 까닭은?","잘 들리게 하려고","소리치면 오히려 듣기 힘들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#9','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C11',2,'match','auto','발표하며 아쉬웠던 점과 고칠 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u5-C11","difficulty":2,"kind":"match","stem":"발표하며 아쉬웠던 점과 고칠 방법을 알맞게 이으세요.","pairs":[{"l":"뒷자리 친구가 잘 못 들었다","r":"잘 들릴 만한 목소리 크기로 말한다"},{"l":"말이 너무 빨라 알아듣기 어려웠다","r":"한 문장씩 천천히 끊어 말한다"},{"l":"종이만 보며 읽었다","r":"듣는 사람을 바라보며 말한다"}],"mis":"K4-1-u5-X11","explanation":["무엇이 아쉬웠나요?","그에 맞는 방법","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_basic#10','kor',4,1,'u5','L02','g4_1_kor_u5_L02_basic','lesson_basic','K4-1-u5-C4',3,'mc','auto','「씨앗 하나의 힘」을 한 문장으로 소개한 것 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X04','K4-1-u5-X26']::text[],false,'{"seq":10,"concept":"K4-1-u5-C4","difficulty":3,"kind":"mc","stem":"「씨앗 하나의 힘」을 한 문장으로 소개한 것 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「씨앗 하나의 힘」은 작은 것도 소중하다는 것을 알려 주는 책이다.","correct":true},{"t":"「씨앗 하나의 힘」은 모두 백 쪽이 넘는 두꺼운 책이다.","mis":"K4-1-u5-X04"},{"t":"「씨앗 하나의 힘」은 표지가 초록색인 책이다.","mis":"K4-1-u5-X04"},{"t":"「씨앗 하나의 힘」은 지난주 금요일에 빌린 책이다.","mis":"K4-1-u5-X26"}],"explanation":["책이 준 느낌은?","겉모습이 아니라","생각을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#1','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C10',2,'mc','auto','친구가 「네 말이 너무 빨라서 알아듣기 어려웠어.」라고 했어요. 다음 발표에서 고칠 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X10','K4-1-u5-X09','K4-1-u5-X08']::text[],false,'{"seq":1,"concept":"K4-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「네 말이 너무 빨라서 알아듣기 어려웠어.」라고 했어요. 다음 발표에서 고칠 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"한 문장씩 끊어 알맞은 빠르기로 말한다","correct":true},{"t":"더 빨리 말해 시간 안에 끝낸다","mis":"K4-1-u5-X10"},{"t":"목소리를 무조건 가장 크게 한다","mis":"K4-1-u5-X09"},{"t":"종이를 보고 그대로 읽는다","mis":"K4-1-u5-X08"}],"explanation":["무엇이 아쉬웠나요?","빠르기","알맞은 빠르기로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#2','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C5',2,'mc','auto','「하람이는 별자리 책을 찾아 북두칠성을 조사했다.」에서 「조사」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X05']::text[],false,'{"seq":2,"concept":"K4-1-u5-C5","difficulty":2,"kind":"mc","stem":"「하람이는 별자리 책을 찾아 북두칠성을 조사했다.」에서 「조사」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"내용을 알기 위해 자세히 살펴봄","correct":true},{"t":"알아낸 것을 여러 사람 앞에 알림","mis":"K4-1-u5-X05"},{"t":"마음을 조이고 정신을 바짝 차림","mis":"K4-1-u5-X05"},{"t":"남이 한 것을 그대로 따라 함","mis":"K4-1-u5-X05"}],"explanation":["책을 찾아서 한 일","알아보기","조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#3','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C9',3,'mc','auto','친구가 「자신 있게 말하려면 무조건 소리쳐야 해.」라고 했어요. 가장 알맞게 대답한 것은 무엇인가요?',ARRAY['K4-1-u5-X09','K4-1-u5-X08']::text[],false,'{"seq":3,"concept":"K4-1-u5-C9","difficulty":3,"kind":"mc","stem":"친구가 「자신 있게 말하려면 무조건 소리쳐야 해.」라고 했어요. 가장 알맞게 대답한 것은 무엇인가요?","options":[{"t":"「목소리를 크게 하는 건 잘 들리게 하려는 거야. 교실 뒤까지 편하게 들리면 돼.」","correct":true},{"t":"「맞아. 가장 크게 소리칠수록 자신 있는 거야.」","mis":"K4-1-u5-X09"},{"t":"「아니야. 목소리는 작을수록 좋아.」","mis":"K4-1-u5-X09"},{"t":"「목소리 크기는 발표와 상관없어.」","mis":"K4-1-u5-X08"}],"explanation":["크게 하는 까닭은?","잘 들리게","소리치기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#4','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C6',3,'mc','auto','「목소리를 찾은 날」이 전하려는 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X06','K4-1-u5-X02']::text[],false,'{"seq":4,"concept":"K4-1-u5-C6","difficulty":3,"kind":"mc","stem":"「목소리를 찾은 날」이 전하려는 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"준비하고 연습하면 떨림을 이기고 자신 있게 말할 수 있다","correct":true},{"t":"발표는 타고난 사람만 잘할 수 있다","mis":"K4-1-u5-X06"},{"t":"무서운 일은 피하는 것이 가장 좋다","mis":"K4-1-u5-X02"},{"t":"목소리가 크면 저절로 자신감이 생긴다","mis":"K4-1-u5-X06"}],"explanation":["하람이는 어떻게 바뀌었나요?","날마다 알아보았어요.","준비가 바탕이에요."],"asset":{"type":"passage","lines":["하람이는 친구들 앞에서 말하는 일이 가장 무서웠다.","발표 숙제를 받자 종이를 접어 가방 깊숙이 넣었다.","하람이는 여름밤마다 보던 북두칠성을 발표하기로 했다.","별자리 책을 찾고, 할머니께 여쭙고, 사진도 확인했다.","날마다 조금씩 알아보는 동안 긴장한 것도 잊었다.","발표 날, 한 문장을 떼자 목소리가 조금씩 커졌다."],"title":"목소리를 찾은 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#5','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C7',3,'mc','auto','인물에게 묻기 활동에서 하람이에게 할 질문을 고르는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X07']::text[],false,'{"seq":5,"concept":"K4-1-u5-C7","difficulty":3,"kind":"mc","stem":"인물에게 묻기 활동에서 하람이에게 할 질문을 고르는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"하람이가 발표를 잘하게 된 과정과 그때의 마음을 묻는다","correct":true},{"t":"하람이의 생김새를 묻는다","mis":"K4-1-u5-X07"},{"t":"이야기에 나오지 않는 하람이의 학원 이름을 묻는다","mis":"K4-1-u5-X07"},{"t":"하람이가 좋아하는 반찬을 묻는다","mis":"K4-1-u5-X07"}],"explanation":["이야기에서 겪은 일","그때의 마음","과정과 마음을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#6','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C8',3,'mc','auto','도윤이가 다음 발표를 더 잘하려면 어떻게 해야 하나요?',ARRAY['K4-1-u5-X08','K4-1-u5-X10','K4-1-u5-X11']::text[],false,'{"seq":6,"concept":"K4-1-u5-C8","difficulty":3,"kind":"mc","stem":"도윤이가 다음 발표를 더 잘하려면 어떻게 해야 하나요?","options":[{"t":"듣는 사람을 바라보며 잘 들리는 크기로 천천히 말한다","correct":true},{"t":"발표 내용을 더 길게 늘인다","mis":"K4-1-u5-X08"},{"t":"원고를 더 빨리 읽어 시간을 줄인다","mis":"K4-1-u5-X10"},{"t":"뒷자리 친구들에게 앞으로 나오라고만 한다","mis":"K4-1-u5-X11"}],"explanation":["원고만 보았어요.","목소리가 작고 빨랐어요.","세 가지를 고쳐요."],"asset":{"type":"passage","lines":["도윤이는 원고만 내려다보며 빠르게 읽어 나갔다.","목소리가 작아 뒷자리 친구들은 잘 듣지 못했다."],"title":"도윤이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#7','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C3',3,'mc','auto','친구가 인상 깊은 장면을 고른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X03','K4-1-u5-X28']::text[],false,'{"seq":7,"concept":"K4-1-u5-C3","difficulty":3,"kind":"mc","stem":"친구가 인상 깊은 장면을 고른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「동생과 다툰 뒤 먼저 사과했던 일이 떠올라 공감했어.」","correct":true},{"t":"「그 장면에 글자가 가장 많아서 골랐어.」","mis":"K4-1-u5-X03"},{"t":"「맨 마지막 쪽이라서 골랐어.」","mis":"K4-1-u5-X03"},{"t":"「아무 장면이나 골라도 까닭은 필요 없어.」","mis":"K4-1-u5-X28"}],"explanation":["내 마음이 움직였나요?","공감한 자리","경험과 이어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#8','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C2',4,'essay','teacher','발표가 떨린다는 친구에게 떨림을 이겨 내는 방법을 두 가지 알려 주고, 그 방법이 도움이 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u5-C2","difficulty":4,"kind":"essay","stem":"발표가 떨린다는 친구에게 떨림을 이겨 내는 방법을 두 가지 알려 주고, 그 방법이 도움이 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 발표할 내용을 미리 찾아 정리한다. 둘째, 집에서 소리 내어 여러 번 연습한다. 무엇을 말할지 잘 알고 연습해 두면 떨려도 말이 막히지 않아 자신감이 생기기 때문이다.","scoring_points":["미리 찾아 정리하는 방법을 썼는가","연습하는 방법을 썼는가","준비가 자신감으로 이어진다는 까닭을 썼는가"]},"explanation":["하람이는 무엇을 했나요?","정리와 연습","까닭도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#9','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C9',4,'essay','teacher','「무조건 큰 목소리로 소리치는 것이 자신 있게 말하는 것이다.」가 알맞지 않은 까닭을 쓰고, 알맞은 목소리 크기가 어느 정도인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u5-C9","difficulty":4,"kind":"essay","stem":"「무조건 큰 목소리로 소리치는 것이 자신 있게 말하는 것이다.」가 알맞지 않은 까닭을 쓰고, 알맞은 목소리 크기가 어느 정도인지 쓰세요.","answer_guide":{"answer":"예: 목소리를 크게 하는 까닭은 듣는 사람에게 잘 들리게 하기 위해서이다. 무조건 소리치면 오히려 듣기 힘들다. 교실 뒤에 앉은 친구까지 편하게 들릴 만큼이면 알맞다.","scoring_points":["크게 하는 까닭을 잘 들리게 하려는 것이라고 썼는가","소리치면 듣기 힘들다고 썼는가","알맞은 크기를 썼는가"]},"explanation":["크게 하는 까닭","소리치면?","교실 뒤까지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L02_challenge#10','kor',4,1,'u5','L02','g4_1_kor_u5_L02_challenge','lesson_challenge','K4-1-u5-C4',4,'essay','teacher','내가 읽은 책 한 권을 한 문장으로 소개하고, 그 문장에 책의 어떤 점을 담았는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u5-C4","difficulty":4,"kind":"essay","stem":"내가 읽은 책 한 권을 한 문장으로 소개하고, 그 문장에 책의 어떤 점을 담았는지 쓰세요.","answer_guide":{"answer":"예: 「달빛 도서관」은 읽은 책을 누군가에게 들려주고 싶어지는 책이다. 책을 읽고 내가 가장 크게 느낀 점을 담았다.","scoring_points":["책 제목을 넣어 한 문장으로 소개했는가","겉모습이 아닌 느낌이나 생각을 담았는가","담은 점을 썼는가"]},"explanation":["책 제목","한 문장","느낌을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#1','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C12',1,'mc','auto','멸종 위기 동물을 소개하는 발표에서 조사 항목으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X12']::text[],false,'{"seq":1,"concept":"K4-1-u5-C12","difficulty":1,"kind":"mc","stem":"멸종 위기 동물을 소개하는 발표에서 조사 항목으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"이름이 몇 글자인지","correct":true},{"t":"어떤 곳에 사는지","mis":"K4-1-u5-X12"},{"t":"무엇을 먹는지","mis":"K4-1-u5-X12"},{"t":"왜 수가 줄어들었는지","mis":"K4-1-u5-X12"}],"explanation":["소개에 꼭 필요한가요?","주제와 이어지나요?","글자 수는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#2','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C13',1,'mc','auto','발표 자료를 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X13']::text[],false,'{"seq":2,"concept":"K4-1-u5-C13","difficulty":1,"kind":"mc","stem":"발표 자료를 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"책이나 백과사전에서 찾아본다","correct":true},{"t":"찾지 않고 짐작으로 채운다","mis":"K4-1-u5-X13"},{"t":"누가 썼는지 모르는 댓글을 그대로 옮긴다","mis":"K4-1-u5-X13"},{"t":"친구가 어디선가 들었다는 이야기를 그대로 쓴다","mis":"K4-1-u5-X13"}],"explanation":["어디에서 찾을까요?","책 · 백과사전","짐작은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#3','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C17',1,'mc','auto','발표에서 「무엇을 발표할지」 알리는 부분은 무엇인가요?',ARRAY['K4-1-u5-X16']::text[],false,'{"seq":3,"concept":"K4-1-u5-C17","difficulty":1,"kind":"mc","stem":"발표에서 「무엇을 발표할지」 알리는 부분은 무엇인가요?","options":[{"t":"시작하는 말","correct":true},{"t":"설명하는 말","mis":"K4-1-u5-X16"},{"t":"끝맺는 말","mis":"K4-1-u5-X16"},{"t":"듣는 사람의 질문","mis":"K4-1-u5-X16"}],"explanation":["처음에 하는 말","무엇을 발표할지","시작하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#4','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C20',1,'mc','auto','친구의 발표를 들을 때 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X19','K4-1-u5-X20']::text[],false,'{"seq":4,"concept":"K4-1-u5-C20","difficulty":1,"kind":"mc","stem":"친구의 발표를 들을 때 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"발표하는 친구를 바라보며 끝까지 듣는다","correct":true},{"t":"궁금한 것이 생기면 발표 도중에 큰 소리로 묻는다","mis":"K4-1-u5-X19"},{"t":"내 발표 원고만 다시 읽는다","mis":"K4-1-u5-X19"},{"t":"못한 점만 찾아 말한다","mis":"K4-1-u5-X20"}],"explanation":["듣는 사람도 참여해요.","바라보며","끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#5','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C14',2,'mc','auto','멸종 위기 동물 발표에 쓰기에 가장 알맞은 자료는 무엇인가요?',ARRAY['K4-1-u5-X13']::text[],false,'{"seq":5,"concept":"K4-1-u5-C14","difficulty":2,"kind":"mc","stem":"멸종 위기 동물 발표에 쓰기에 가장 알맞은 자료는 무엇인가요?","options":[{"t":"국립생물자원관 누리집에 실린 동물 소개","correct":true},{"t":"누가 썼는지 알 수 없는 짧은 댓글","mis":"K4-1-u5-X13"},{"t":"친구가 어디선가 들었다는 이야기","mis":"K4-1-u5-X13"},{"t":"글쓴이가 없는 재미있는 게시물","mis":"K4-1-u5-X13"}],"explanation":["누가 만들었나요?","분명한 곳","믿을 만한 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#6','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C15',2,'mc','auto','조사한 자료를 가져다 발표에 쓸 때 해야 할 일은 무엇인가요?',ARRAY['K4-1-u5-X14']::text[],false,'{"seq":6,"concept":"K4-1-u5-C15","difficulty":2,"kind":"mc","stem":"조사한 자료를 가져다 발표에 쓸 때 해야 할 일은 무엇인가요?","options":[{"t":"어디서 가져왔는지 출처를 밝힌다","correct":true},{"t":"내가 처음 알아낸 것처럼 말한다","mis":"K4-1-u5-X14"},{"t":"출처는 밝히지 않는 것이 예의이다","mis":"K4-1-u5-X14"},{"t":"출처 자리에 내 이름을 쓴다","mis":"K4-1-u5-X14"}],"explanation":["어디서 가져왔나요?","밝혀요.","출처예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#7','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C16',2,'match','auto','장수풍뎅이 발표를 준비하며 알고 싶은 점과 찾은 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-1-u5-C16","difficulty":2,"kind":"match","stem":"장수풍뎅이 발표를 준비하며 알고 싶은 점과 찾은 내용을 알맞게 이으세요.","pairs":[{"l":"생김새","r":"수컷 머리에 끝이 갈라진 긴 뿔이 있다"},{"l":"먹이","r":"참나무에서 나오는 진을 먹는다"},{"l":"애벌레가 자라는 곳","r":"썩은 나무나 낙엽이 쌓인 흙 속"}],"mis":"K4-1-u5-X15","explanation":["어떻게 생겼나?","무엇을 먹나?","어디서 자라나?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#8','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C18',2,'mc','auto','「장수풍뎅이 성충은 참나무 수액을 섭취한다.」를 듣는 사람이 알아듣기 쉽게 바꾼 것은 무엇인가요?',ARRAY['K4-1-u5-X17','K4-1-u5-X12']::text[],false,'{"seq":8,"concept":"K4-1-u5-C18","difficulty":2,"kind":"mc","stem":"「장수풍뎅이 성충은 참나무 수액을 섭취한다.」를 듣는 사람이 알아듣기 쉽게 바꾼 것은 무엇인가요?","options":[{"t":"「어른 장수풍뎅이는 참나무에서 나오는 진을 먹습니다.」","correct":true},{"t":"「장수풍뎅이 성충은 참나무 수액을 섭취합니다.」","mis":"K4-1-u5-X17"},{"t":"「먹이는 자료에 나온 그대로입니다.」","mis":"K4-1-u5-X17"},{"t":"「장수풍뎅이의 먹이는 말하지 않겠습니다.」","mis":"K4-1-u5-X12"}],"explanation":["어려운 말은?","성충 · 수액 · 섭취","쉬운 말로 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#9','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C19',2,'mc','auto','발표하면서 사진 자료를 보여 줄 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X18','K4-1-u5-X09']::text[],false,'{"seq":9,"concept":"K4-1-u5-C19","difficulty":2,"kind":"mc","stem":"발표하면서 사진 자료를 보여 줄 때 알맞은 것은 무엇인가요?","options":[{"t":"손으로 가리켜 어디를 보면 되는지 알린다","correct":true},{"t":"사진을 보여 주기만 하고 아무 말도 하지 않는다","mis":"K4-1-u5-X18"},{"t":"사진을 등지고 원고만 읽는다","mis":"K4-1-u5-X18"},{"t":"사진을 보여 줄 때는 가장 큰 소리로 소리친다","mis":"K4-1-u5-X09"}],"explanation":["새 자료를 보여 줄 때","어디를 봐야 하나요?","가리켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_basic#10','kor',4,1,'u5','L04','g4_1_kor_u5_L04_basic','lesson_basic','K4-1-u5-C21',3,'mc','auto','내 발표를 되돌아볼 때 살필 것을 바르게 모은 것은 무엇인가요?',ARRAY['K4-1-u5-X21']::text[],false,'{"seq":10,"concept":"K4-1-u5-C21","difficulty":3,"kind":"mc","stem":"내 발표를 되돌아볼 때 살필 것을 바르게 모은 것은 무엇인가요?","options":[{"t":"주제와 관련된 내용인가 · 믿을 만한 자료이고 출처를 밝혔나 · 쉬운 말로 말했나","correct":true},{"t":"목소리가 가장 컸나 하나만 살핀다","mis":"K4-1-u5-X21"},{"t":"발표가 다른 친구보다 짧았나만 살핀다","mis":"K4-1-u5-X21"},{"t":"원고의 글자 수가 얼마나 많았나를 살핀다","mis":"K4-1-u5-X21"}],"explanation":["하나만 볼까요?","주제 · 자료 · 말","여러 기준으로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#1','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C17',2,'mc','auto','장수풍뎅이 발표의 끝맺는 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X16']::text[],false,'{"seq":1,"concept":"K4-1-u5-C17","difficulty":2,"kind":"mc","stem":"장수풍뎅이 발표의 끝맺는 말로 알맞은 것은 무엇인가요?","options":[{"t":"「지금까지 장수풍뎅이의 생김새와 먹이, 자라는 곳을 알아보았습니다. 들어 주셔서 고맙습니다.」","correct":true},{"t":"「지금부터 장수풍뎅이를 소개하겠습니다.」","mis":"K4-1-u5-X16"},{"t":"「장수풍뎅이 수컷은 머리에 긴 뿔이 있습니다.」","mis":"K4-1-u5-X16"},{"t":"「장수풍뎅이 애벌레는 썩은 나무에서 자랍니다.」","mis":"K4-1-u5-X16"}],"explanation":["마칠 때 하는 말","정리하고 인사","끝맺는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#2','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C12',2,'mc','auto','주제가 「우리 학교 도서실을 소개합니다」일 때 조사 항목으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X12']::text[],false,'{"seq":2,"concept":"K4-1-u5-C12","difficulty":2,"kind":"mc","stem":"주제가 「우리 학교 도서실을 소개합니다」일 때 조사 항목으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"도서실 문 손잡이가 몇 개인지","correct":true},{"t":"언제 문을 여는지","mis":"K4-1-u5-X12"},{"t":"책을 빌리는 방법","mis":"K4-1-u5-X12"},{"t":"어떤 책이 많은지","mis":"K4-1-u5-X12"}],"explanation":["도서실을 소개하려면","듣는 친구에게 필요한 것","손잡이 수는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#3','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C14',3,'mc','auto','장수풍뎅이에 대해 두 곳의 자료 내용이 서로 달랐어요. 가장 알맞게 한 것은 무엇인가요?',ARRAY['K4-1-u5-X13']::text[],false,'{"seq":3,"concept":"K4-1-u5-C14","difficulty":3,"kind":"mc","stem":"장수풍뎅이에 대해 두 곳의 자료 내용이 서로 달랐어요. 가장 알맞게 한 것은 무엇인가요?","options":[{"t":"누가 만든 자료인지 살펴 믿을 만한 곳의 내용을 고르고 출처를 밝힌다","correct":true},{"t":"더 신기한 쪽을 고른다","mis":"K4-1-u5-X13"},{"t":"둘 다 버리고 짐작한 내용을 쓴다","mis":"K4-1-u5-X13"},{"t":"먼저 본 쪽을 그대로 쓴다","mis":"K4-1-u5-X13"}],"explanation":["누가 만들었나요?","믿을 만한 곳","출처도 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#4','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C18',3,'mc','auto','발표에서 어려운 말을 쉬운 말로 바꾸어 말하는 까닭은 무엇인가요?',ARRAY['K4-1-u5-X17']::text[],false,'{"seq":4,"concept":"K4-1-u5-C18","difficulty":3,"kind":"mc","stem":"발표에서 어려운 말을 쉬운 말로 바꾸어 말하는 까닭은 무엇인가요?","options":[{"t":"듣는 친구가 알아듣고 내용이 잘 전해지게 하려고","correct":true},{"t":"발표 시간을 늘리려고","mis":"K4-1-u5-X17"},{"t":"어려운 말은 틀린 말이라서","mis":"K4-1-u5-X17"},{"t":"자료의 뜻을 바꾸려고","mis":"K4-1-u5-X17"}],"explanation":["누가 듣나요?","알아들어야 전해져요.","쉬운 말로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#5','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C19',3,'mc','auto','은솔이에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X10','K4-1-u5-X18','K4-1-u5-X09']::text[],false,'{"seq":5,"concept":"K4-1-u5-C19","difficulty":3,"kind":"mc","stem":"은솔이에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「중요한 곳은 목소리를 조금 크게 하고, 사진은 손으로 가리키며 친구들과 눈을 맞춰 봐.」","correct":true},{"t":"「자료를 더 빠르게 읽어 봐.」","mis":"K4-1-u5-X10"},{"t":"「사진은 빼고 자료만 읽어.」","mis":"K4-1-u5-X18"},{"t":"「처음부터 끝까지 가장 큰 소리로 읽어.」","mis":"K4-1-u5-X09"}],"explanation":["그대로 읽었어요.","사진을 가리키지 않았어요.","주의할 점을 떠올려요."],"asset":{"type":"passage","lines":["은솔이는 조사한 자료를 처음부터 끝까지 그대로 읽었다.","사진을 보여 줄 때도 고개를 숙인 채 원고만 보았다.","친구들은 사진의 어디를 봐야 할지 몰랐다."],"title":"은솔이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#6','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C20',3,'mc','auto','친구의 발표를 듣고 구체적으로 칭찬한 말은 무엇인가요?',ARRAY['K4-1-u5-X20']::text[],false,'{"seq":6,"concept":"K4-1-u5-C20","difficulty":3,"kind":"mc","stem":"친구의 발표를 듣고 구체적으로 칭찬한 말은 무엇인가요?","options":[{"t":"「사진을 손으로 가리키며 설명해서 뿔 모양이 잘 보였어.」","correct":true},{"t":"「잘했어.」","mis":"K4-1-u5-X20"},{"t":"「목소리가 작아서 별로였어.」","mis":"K4-1-u5-X20"},{"t":"「내 발표가 더 재미있었어.」","mis":"K4-1-u5-X20"}],"explanation":["무엇을 잘했나요?","짚어서 말해요.","구체적인 칭찬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#7','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C15',3,'mc','auto','발표할 때 자료의 출처를 밝히는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X14']::text[],false,'{"seq":7,"concept":"K4-1-u5-C15","difficulty":3,"kind":"mc","stem":"발표할 때 자료의 출처를 밝히는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"듣는 사람이 내용을 믿을 수 있고, 자료를 만든 사람을 존중할 수 있어서","correct":true},{"t":"출처를 밝히면 발표가 길어 보여서","mis":"K4-1-u5-X14"},{"t":"출처는 선생님만 알면 되어서","mis":"K4-1-u5-X14"},{"t":"출처를 밝히면 내가 찾은 것이 아니게 되어서","mis":"K4-1-u5-X14"}],"explanation":["듣는 사람은?","만든 사람은?","믿음과 존중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#8','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C17',4,'essay','teacher','발표 주제를 하나 정하고, 시작하는 말 · 설명하는 말 · 끝맺는 말을 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u5-C17","difficulty":4,"kind":"essay","stem":"발표 주제를 하나 정하고, 시작하는 말 · 설명하는 말 · 끝맺는 말을 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 주제 — 애반딧불이. 시작하는 말: 지금부터 애반딧불이를 소개하겠습니다. 설명하는 말: 애반딧불이 애벌레는 깨끗한 냇물에 살며 다슬기를 먹습니다. 끝맺는 말: 지금까지 애반딧불이를 알아보았습니다. 들어 주셔서 고맙습니다.","scoring_points":["주제를 정했는가","세 부분을 차례대로 썼는가","부분마다 알맞은 내용을 담았는가"]},"explanation":["무엇을 발표할지","조사한 내용","정리하고 인사"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#9','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C18',4,'essay','teacher','「애반딧불이 유충은 청정한 하천에 서식한다.」를 듣는 친구가 알아듣기 쉬운 말로 바꾸어 쓰고, 어떤 낱말을 어떻게 바꾸었는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u5-C18","difficulty":4,"kind":"essay","stem":"「애반딧불이 유충은 청정한 하천에 서식한다.」를 듣는 친구가 알아듣기 쉬운 말로 바꾸어 쓰고, 어떤 낱말을 어떻게 바꾸었는지 쓰세요.","answer_guide":{"answer":"예: 애반딧불이 애벌레는 깨끗한 냇물에 삽니다. 유충은 애벌레로, 청정한 하천은 깨끗한 냇물로, 서식한다는 삽니다로 바꾸었다.","scoring_points":["쉬운 말로 바꾼 문장을 썼는가","뜻이 그대로인가","바꾼 낱말을 짚었는가"]},"explanation":["유충","청정한 하천","서식한다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L04_challenge#10','kor',4,1,'u5','L04','g4_1_kor_u5_L04_challenge','lesson_challenge','K4-1-u5-C15',4,'essay','teacher','발표 자료를 고르고 쓸 때 지켜야 할 점을 두 가지 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u5-C15","difficulty":4,"kind":"essay","stem":"발표 자료를 고르고 쓸 때 지켜야 할 점을 두 가지 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 누가 만들었는지 분명한 믿을 만한 곳의 자료를 고른다. 둘째, 자료를 어디서 가져왔는지 출처를 밝힌다. 그래야 듣는 사람이 내용을 믿을 수 있고 자료를 만든 사람도 존중할 수 있다.","scoring_points":["믿을 만한 자료를 고른다고 썼는가","출처를 밝힌다고 썼는가","까닭을 썼는가"]},"explanation":["누가 만들었나요?","어디서 가져왔나요?","까닭도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#1','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C22',1,'mc','auto','독서 감상문은 어떤 글인가요?',ARRAY['K4-1-u5-X22']::text[],false,'{"seq":1,"concept":"K4-1-u5-C22","difficulty":1,"kind":"mc","stem":"독서 감상문은 어떤 글인가요?","options":[{"t":"책을 읽고 생각이나 느낌을 쓴 글","correct":true},{"t":"책의 줄거리를 처음부터 끝까지 옮긴 글","mis":"K4-1-u5-X22"},{"t":"책을 사려고 값을 적어 둔 글","mis":"K4-1-u5-X22"},{"t":"책의 쪽수와 글자 수를 센 글","mis":"K4-1-u5-X22"}],"explanation":["책을 읽고","내 마음","생각이나 느낌을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#2','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C24',1,'mc','auto','독서 감상문에 들어갈 내용이 아닌 것은 무엇인가요?',ARRAY['K4-1-u5-X24']::text[],false,'{"seq":2,"concept":"K4-1-u5-C24","difficulty":1,"kind":"mc","stem":"독서 감상문에 들어갈 내용이 아닌 것은 무엇인가요?","options":[{"t":"책의 쪽수와 무게","correct":true},{"t":"책을 읽은 까닭","mis":"K4-1-u5-X24"},{"t":"인상 깊은 장면","mis":"K4-1-u5-X24"},{"t":"생각이나 느낌","mis":"K4-1-u5-X24"}],"explanation":["들어갈 내용을 떠올려요.","제목부터 느낌까지","무게는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#3','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C26',1,'mc','auto','독서 감상문에 「책을 읽은 까닭」으로 쓸 만한 것은 무엇인가요?',ARRAY['K4-1-u5-X26']::text[],false,'{"seq":3,"concept":"K4-1-u5-C26","difficulty":1,"kind":"mc","stem":"독서 감상문에 「책을 읽은 까닭」으로 쓸 만한 것은 무엇인가요?","options":[{"t":"표지 그림이 마음에 들어 도서관에서 골랐다","correct":true},{"t":"이 책은 모두 백스무 쪽이다","mis":"K4-1-u5-X26"},{"t":"책을 다 읽는 데 사십 분이 걸렸다","mis":"K4-1-u5-X26"},{"t":"책값이 얼마인지 모른다","mis":"K4-1-u5-X26"}],"explanation":["어떻게 만났나요?","고르게 된 계기","읽은 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#4','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C23',1,'mc','auto','독서 감상문을 쓰면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X23']::text[],false,'{"seq":4,"concept":"K4-1-u5-C23","difficulty":1,"kind":"mc","stem":"독서 감상문을 쓰면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"책을 읽고 느낀 감동을 오래 기억할 수 있다","correct":true},{"t":"책을 더 빨리 읽을 수 있다","mis":"K4-1-u5-X23"},{"t":"책을 다시 읽지 않아도 시험을 잘 본다","mis":"K4-1-u5-X23"},{"t":"친구와 느낌을 나누지 않아도 된다","mis":"K4-1-u5-X23"}],"explanation":["기억 · 나눔 · 소개","빨리 읽기?","감동을 오래 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#5','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C32',2,'match','auto','「우산 가게 할아버지」 감상문의 각 부분이 무엇을 쓴 곳인지 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u5-C32","difficulty":2,"kind":"match","stem":"「우산 가게 할아버지」 감상문의 각 부분이 무엇을 쓴 곳인지 이으세요.","pairs":[{"l":"① 노란 우산이 눈에 들어와 골랐다","r":"책을 읽은 까닭"},{"l":"② 할아버지는 날마다 가게 문을 연다","r":"책의 내용"},{"l":"⑥ 고쳐 쓸 수 있는지 먼저 살펴봐야겠다","r":"생각이나 느낌"}],"mis":"K4-1-u5-X32","explanation":["책 이야기인가요?","내 마음인가요?","먼저 갈라요."],"asset":{"type":"passage","lines":["① 표지에 그려진 노란 우산이 눈에 들어와 이 책을 골랐다.","② 골목 끝 우산 가게 할아버지는 날마다 가게 문을 연다.","③ 할아버지는 비를 맞고 선 아이에게 우산을 내어 준다.","④ 할아버지가 버려진 우산을 하나하나 고치는 장면이 가장 기억에 남았다.","⑤ 버려진 것이 다시 쓰이는 모습이 놀라웠기 때문이다.","⑥ 앞으로는 고쳐 쓸 수 있는지 먼저 살펴봐야겠다."],"title":"「우산 가게 할아버지」를 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#6','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C28',2,'mc','auto','독서 감상문에 인상 깊은 장면을 쓸 때 함께 써야 할 것은 무엇인가요?',ARRAY['K4-1-u5-X28','K4-1-u5-X03']::text[],false,'{"seq":6,"concept":"K4-1-u5-C28","difficulty":2,"kind":"mc","stem":"독서 감상문에 인상 깊은 장면을 쓸 때 함께 써야 할 것은 무엇인가요?","options":[{"t":"그 장면이 기억에 남은 까닭","correct":true},{"t":"그 장면이 몇 쪽에 있는지","mis":"K4-1-u5-X28"},{"t":"그 장면에 나온 글자 수","mis":"K4-1-u5-X03"},{"t":"다른 책에 나온 장면","mis":"K4-1-u5-X28"}],"explanation":["왜 기억에 남았나요?","까닭","함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#7','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C30',2,'mc','auto','독서 감상문에 책 이야기와 내 생각이 함께 있어야 하는 까닭은 무엇인가요?',ARRAY['K4-1-u5-X30']::text[],false,'{"seq":7,"concept":"K4-1-u5-C30","difficulty":2,"kind":"mc","stem":"독서 감상문에 책 이야기와 내 생각이 함께 있어야 하는 까닭은 무엇인가요?","options":[{"t":"줄거리만 있으면 내 마음이 빠지고, 느낌만 있으면 무슨 이야기인지 알 수 없어서","correct":true},{"t":"줄거리만 있어도 감상문이 되어서","mis":"K4-1-u5-X30"},{"t":"느낌만 있어도 무슨 책인지 다 알 수 있어서","mis":"K4-1-u5-X30"},{"t":"둘을 함께 쓰면 글이 길어 보여서","mis":"K4-1-u5-X30"}],"explanation":["줄거리만 있으면?","느낌만 있으면?","둘이 함께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#8','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C25',2,'mc','auto','독서 감상문의 제목을 짓는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X25']::text[],false,'{"seq":8,"concept":"K4-1-u5-C25","difficulty":2,"kind":"mc","stem":"독서 감상문의 제목을 짓는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"책의 주제나 전체 느낌이 드러나게 짓는다","correct":true},{"t":"책 제목을 그대로만 쓴다","mis":"K4-1-u5-X25"},{"t":"제목은 붙이지 않는다","mis":"K4-1-u5-X25"},{"t":"책의 첫 문장을 그대로 옮긴다","mis":"K4-1-u5-X25"}],"explanation":["제목에는 무엇이?","주제나 느낌","드러나게 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#9','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C29',2,'mc','auto','「우산 가게 할아버지」를 읽고 쓴 문장 가운데 생각이나 느낌을 가장 잘 드러낸 것은 무엇인가요?',ARRAY['K4-1-u5-X29','K4-1-u5-X27','K4-1-u5-X26']::text[],false,'{"seq":9,"concept":"K4-1-u5-C29","difficulty":2,"kind":"mc","stem":"「우산 가게 할아버지」를 읽고 쓴 문장 가운데 생각이나 느낌을 가장 잘 드러낸 것은 무엇인가요?","options":[{"t":"나도 망가진 물건을 바로 버리지 않고 고쳐 써 보겠다고 다짐했다.","correct":true},{"t":"재미있었다.","mis":"K4-1-u5-X29"},{"t":"할아버지는 날마다 가게 문을 연다.","mis":"K4-1-u5-X27"},{"t":"이 책은 학교 도서관에 있다.","mis":"K4-1-u5-X26"}],"explanation":["깨달은 점","다짐","자세히 쓴 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_basic#10','kor',4,1,'u5','L07','g4_1_kor_u5_L07_basic','lesson_basic','K4-1-u5-C31',3,'mc','auto','다온이의 독서 감상문에서 가장 아쉬운 점은 무엇인가요?',ARRAY['K4-1-u5-X30','K4-1-u5-X31','K4-1-u5-X25']::text[],false,'{"seq":10,"concept":"K4-1-u5-C31","difficulty":3,"kind":"mc","stem":"다온이의 독서 감상문에서 가장 아쉬운 점은 무엇인가요?","options":[{"t":"줄거리만 길고 인상 깊은 장면과 생각이나 느낌이 거의 없다","correct":true},{"t":"책의 내용이 하나도 없다","mis":"K4-1-u5-X30"},{"t":"문장이 너무 짧다","mis":"K4-1-u5-X31"},{"t":"제목이 붙어 있다","mis":"K4-1-u5-X25"}],"explanation":["책 이야기는 있나요?","내 마음은 있나요?","줄거리만 길어요."],"asset":{"type":"passage","lines":["거북이 산 너머 마을로 가는 짐을 맡았다.","첫째 날에는 언덕을 넘었다.","둘째 날에는 비가 와서 나뭇잎 아래에서 쉬었다.","셋째 날에는 냇물을 건넜다.","넷째 날에 마을에 도착해 짐을 건넸다.","재미있었다."],"title":"다온이의 독서 감상문 — 「느림보 거북 택배」를 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#1','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C27',2,'mc','auto','독서 감상문의 「책의 내용」 부분에 쓰는 것은 무엇인가요?',ARRAY['K4-1-u5-X27','K4-1-u5-X26','K4-1-u5-X31']::text[],false,'{"seq":1,"concept":"K4-1-u5-C27","difficulty":2,"kind":"mc","stem":"독서 감상문의 「책의 내용」 부분에 쓰는 것은 무엇인가요?","options":[{"t":"인물과 배경, 줄거리를 간추린 내용","correct":true},{"t":"책을 읽고 한 다짐","mis":"K4-1-u5-X27"},{"t":"책값과 산 곳","mis":"K4-1-u5-X26"},{"t":"책의 모든 문장","mis":"K4-1-u5-X31"}],"explanation":["누가 · 어디서 · 무슨 일","간추려요.","인물 · 배경 · 줄거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#2','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C24',2,'mc','auto','독서 감상문에 들어갈 내용을 바르게 모은 것은 무엇인가요?',ARRAY['K4-1-u5-X24','K4-1-u5-X30','K4-1-u5-X31']::text[],false,'{"seq":2,"concept":"K4-1-u5-C24","difficulty":2,"kind":"mc","stem":"독서 감상문에 들어갈 내용을 바르게 모은 것은 무엇인가요?","options":[{"t":"제목 · 읽은 까닭 · 책의 내용 · 인상 깊은 장면 · 생각이나 느낌","correct":true},{"t":"제목 · 쪽수 · 책값 · 지은이 나이 · 출판사 전화번호","mis":"K4-1-u5-X24"},{"t":"읽은 까닭 · 줄거리","mis":"K4-1-u5-X30"},{"t":"인상 깊은 장면 · 책의 모든 문장","mis":"K4-1-u5-X31"}],"explanation":["책 이야기와","내 마음이 함께","빠짐없이 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#3','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C25',3,'mc','auto','유나의 감상문에 어울리는 제목으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X25']::text[],false,'{"seq":3,"concept":"K4-1-u5-C25","difficulty":3,"kind":"mc","stem":"유나의 감상문에 어울리는 제목으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「띄우지 말고 건네요」","correct":true},{"t":"「종이배 우체부」","mis":"K4-1-u5-X25"},{"t":"「바닷가」","mis":"K4-1-u5-X25"},{"t":"「책 읽은 날」","mis":"K4-1-u5-X25"}],"explanation":["유나가 느낀 것은?","⑤를 봐요.","느낌이 드러난 제목이에요."],"asset":{"type":"passage","lines":["① 친구가 표지의 하얀 종이배가 예쁘다며 권해 주어 읽게 되었다.","② 해오는 미안하다는 말을 못 하고 종이배에만 적어 띄운다.","③ 할머니가 젖은 종이배를 건네는 장면이 가장 기억에 남았다.","④ 나도 하고 싶은 말을 마음속에만 담아 둔 적이 있어서 뜨끔했기 때문이다.","⑤ 이제는 할 말이 있으면 용기를 내어 직접 건네 보겠다."],"title":"유나의 독서 감상문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#4','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C31',3,'mc','auto','줄거리가 너무 길어질 때 줄이는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X31','K4-1-u5-X30']::text[],false,'{"seq":4,"concept":"K4-1-u5-C31","difficulty":3,"kind":"mc","stem":"줄거리가 너무 길어질 때 줄이는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"여러 문장을 점점 줄여 이야기를 알아볼 만큼만 남긴다","correct":true},{"t":"모든 장면을 빠짐없이 적는다","mis":"K4-1-u5-X31"},{"t":"줄거리를 아예 쓰지 않는다","mis":"K4-1-u5-X30"},{"t":"책의 문장을 그대로 베껴 쓴다","mis":"K4-1-u5-X31"}],"explanation":["알아볼 만큼만","점점 줄여요.","간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#5','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C32',3,'mc','auto','「아이는 우산을 돌려주러 갔다가 할아버지가 버려진 우산을 고치는 모습을 본다.」는 감상문에서 무엇을 쓴 곳인가요?',ARRAY['K4-1-u5-X32']::text[],false,'{"seq":5,"concept":"K4-1-u5-C32","difficulty":3,"kind":"mc","stem":"「아이는 우산을 돌려주러 갔다가 할아버지가 버려진 우산을 고치는 모습을 본다.」는 감상문에서 무엇을 쓴 곳인가요?","options":[{"t":"책의 내용","correct":true},{"t":"생각이나 느낌","mis":"K4-1-u5-X32"},{"t":"책을 읽은 까닭","mis":"K4-1-u5-X32"},{"t":"제목","mis":"K4-1-u5-X32"}],"explanation":["누가 한 일인가요?","책 속 이야기","책의 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#6','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C28',3,'mc','auto','인상 깊은 장면을 까닭과 함께 쓴 것은 무엇인가요?',ARRAY['K4-1-u5-X28','K4-1-u5-X27','K4-1-u5-X29']::text[],false,'{"seq":6,"concept":"K4-1-u5-C28","difficulty":3,"kind":"mc","stem":"인상 깊은 장면을 까닭과 함께 쓴 것은 무엇인가요?","options":[{"t":"할아버지가 우산을 고치는 장면이 기억에 남았다. 버려진 것이 다시 쓰이는 모습이 놀라웠기 때문이다.","correct":true},{"t":"할아버지가 우산을 고치는 장면이 기억에 남았다.","mis":"K4-1-u5-X28"},{"t":"할아버지는 날마다 가게 문을 연다.","mis":"K4-1-u5-X27"},{"t":"이 책은 재미있었다.","mis":"K4-1-u5-X29"}],"explanation":["장면","왜 남았나요?","까닭까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#7','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C23',3,'mc','auto','친구가 「감상문은 선생님께 내려고 쓰는 거야.」라고 했어요. 가장 알맞게 대답한 것은 무엇인가요?',ARRAY['K4-1-u5-X23','K4-1-u5-X22']::text[],false,'{"seq":7,"concept":"K4-1-u5-C23","difficulty":3,"kind":"mc","stem":"친구가 「감상문은 선생님께 내려고 쓰는 거야.」라고 했어요. 가장 알맞게 대답한 것은 무엇인가요?","options":[{"t":"「내가 느낀 것을 다른 사람과 나누고, 감동을 오래 기억하려고 쓰는 거야.」","correct":true},{"t":"「맞아. 내고 나면 다시 볼 일은 없어.」","mis":"K4-1-u5-X23"},{"t":"「책을 빨리 읽으려고 쓰는 거야.」","mis":"K4-1-u5-X23"},{"t":"「줄거리를 외우려고 쓰는 거야.」","mis":"K4-1-u5-X22"}],"explanation":["누구와 나누나요?","오래 기억해요.","나누려고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#8','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C30',4,'essay','teacher','줄거리만 있는 감상문과 느낌만 있는 감상문은 각각 무엇이 아쉬운지 쓰고, 두 가지가 함께 있어야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u5-C30","difficulty":4,"kind":"essay","stem":"줄거리만 있는 감상문과 느낌만 있는 감상문은 각각 무엇이 아쉬운지 쓰고, 두 가지가 함께 있어야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 줄거리만 있으면 글쓴이의 생각이나 느낌이 빠져 독서록처럼 된다. 느낌만 있으면 읽는 사람이 무슨 이야기인지 알 수 없다. 그래서 책 이야기와 내 마음이 함께 있어야 감동을 제대로 나눌 수 있다.","scoring_points":["줄거리만 있을 때 아쉬운 점을 썼는가","느낌만 있을 때 아쉬운 점을 썼는가","함께 있어야 하는 까닭을 썼는가"]},"explanation":["줄거리만?","느낌만?","나누려면"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#9','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C28',4,'essay','teacher','최근에 읽은 책에서 인상 깊은 장면을 하나 고르고, 그 장면이 기억에 남은 까닭을 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u5-C28","difficulty":4,"kind":"essay","stem":"최근에 읽은 책에서 인상 깊은 장면을 하나 고르고, 그 장면이 기억에 남은 까닭을 함께 쓰세요.","answer_guide":{"answer":"예: 「달빛 도서관」에서 연우가 짝꿍에게 이야기를 들려주는 장면이 가장 기억에 남았다. 혼자 읽은 책이 두 사람을 이어 주는 모습이 따뜻했기 때문이다.","scoring_points":["책 제목과 장면을 썼는가","기억에 남은 까닭을 썼는가","장면과 까닭이 이어지는가"]},"explanation":["어떤 장면?","왜?","이어서 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L07_challenge#10','kor',4,1,'u5','L07','g4_1_kor_u5_L07_challenge','lesson_challenge','K4-1-u5-C31',4,'essay','teacher','다온이의 감상문을 고쳐 쓰려고 해요. 무엇을 줄이고 무엇을 더 쓰면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u5-C31","difficulty":4,"kind":"essay","stem":"다온이의 감상문을 고쳐 쓰려고 해요. 무엇을 줄이고 무엇을 더 쓰면 좋을지 쓰세요.","answer_guide":{"answer":"예: 첫째 날부터 넷째 날까지 늘어놓은 줄거리는 「거북이 비와 냇물을 지나 끝까지 짐을 나른다」처럼 간추린다. 대신 가장 기억에 남은 장면과 그 까닭, 책을 읽고 든 생각이나 다짐을 자세히 덧붙인다.","scoring_points":["줄거리를 간추린다고 썼는가","인상 깊은 장면과 까닭을 더한다고 썼는가","생각이나 느낌을 더한다고 썼는가"]},"explanation":["줄일 곳","더할 곳","책 이야기와 내 마음"],"asset":{"type":"passage","lines":["거북이 산 너머 마을로 가는 짐을 맡았다.","첫째 날에는 언덕을 넘었다.","둘째 날에는 비가 와서 나뭇잎 아래에서 쉬었다.","셋째 날에는 냇물을 건넜다.","넷째 날에 마을에 도착해 짐을 건넸다.","재미있었다."],"title":"다온이의 독서 감상문 — 「느림보 거북 택배」를 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#1','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C33',1,'mc','auto','독서 감상문을 쓸 책을 고르는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X33']::text[],false,'{"seq":1,"concept":"K4-1-u5-C33","difficulty":1,"kind":"mc","stem":"독서 감상문을 쓸 책을 고르는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"가장 얇아서 빨리 읽을 수 있는 책을 고른다","correct":true},{"t":"내가 좋아하는 분야의 책을 고른다","mis":"K4-1-u5-X33"},{"t":"재미있게 읽은 책의 지은이가 쓴 다른 책을 고른다","mis":"K4-1-u5-X33"},{"t":"친구나 선생님이 추천해 준 책을 고른다","mis":"K4-1-u5-X33"}],"explanation":["읽고 싶어지는 까닭","얇기?","빨리 읽기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#2','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C35',1,'mc','auto','독서 감상문의 처음 부분에 쓰기 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X35']::text[],false,'{"seq":2,"concept":"K4-1-u5-C35","difficulty":1,"kind":"mc","stem":"독서 감상문의 처음 부분에 쓰기 알맞은 것은 무엇인가요?","options":[{"t":"책을 읽게 된 까닭","correct":true},{"t":"책을 읽고 한 다짐","mis":"K4-1-u5-X35"},{"t":"인상 깊은 장면","mis":"K4-1-u5-X35"},{"t":"책의 마지막 장면","mis":"K4-1-u5-X35"}],"explanation":["처음에는?","어떻게 만났나요?","읽게 된 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#3','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C36',1,'mc','auto','독서 감상문에서 문단은 어디에서 나누나요?',ARRAY['K4-1-u5-X36']::text[],false,'{"seq":3,"concept":"K4-1-u5-C36","difficulty":1,"kind":"mc","stem":"독서 감상문에서 문단은 어디에서 나누나요?","options":[{"t":"내용이 바뀌는 자리","correct":true},{"t":"세 줄마다","mis":"K4-1-u5-X36"},{"t":"쉼표가 나올 때마다","mis":"K4-1-u5-X36"},{"t":"문단은 나누지 않는다","mis":"K4-1-u5-X36"}],"explanation":["무엇이 바뀌나요?","내용","바뀌는 자리에서 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#4','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C39',1,'mc','auto','독서 감상문을 쓰는 형식에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u5-X38']::text[],false,'{"seq":4,"concept":"K4-1-u5-C39","difficulty":1,"kind":"mc","stem":"독서 감상문을 쓰는 형식에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"편지, 일기, 만화, 인터뷰 같은 여러 형식으로 쓸 수 있다","correct":true},{"t":"정해진 한 가지 형식으로만 써야 한다","mis":"K4-1-u5-X38"},{"t":"편지로 쓰면 감상문이 아니다","mis":"K4-1-u5-X38"},{"t":"그림으로 나타내면 감상문이 아니다","mis":"K4-1-u5-X38"}],"explanation":["여러 가지","편지 · 일기 · 만화","형식은 자유로워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#5','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C34',2,'match','auto','「종이배 우체부」 감상문에 쓸 내용을 항목에 맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u5-C34","difficulty":2,"kind":"match","stem":"「종이배 우체부」 감상문에 쓸 내용을 항목에 맞게 이으세요.","pairs":[{"l":"책을 읽은 까닭","r":"친구가 표지가 예쁘다며 권해 주었다"},{"l":"인상 깊은 장면","r":"할머니가 젖은 종이배를 건네는 장면"},{"l":"생각이나 느낌","r":"할 말이 있으면 직접 건네 보겠다"}],"mis":"K4-1-u5-X34","explanation":["어떻게 만났나요?","기억에 남은 장면","내 다짐"],"asset":{"type":"passage","lines":["① 바닷가 마을 해오는 하고 싶은 말을 꺼내는 일이 서툴렀다.","② 이사 간 보라에게 미안하다는 말을 끝내 하지 못했다.","③ 해오는 그 말을 종이배에 적어 날마다 냇물에 띄웠다.","④ 냇가 할머니가 젖은 종이배를 건네며 말했다.","⑤ \"말은 띄우는 게 아니라 건네는 거란다.\"","⑥ 해오는 보라에게 전화를 걸어 처음으로 미안하다고 말했다."],"title":"종이배 우체부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#6','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C37',2,'mc','auto','잘 쓴 독서 감상문의 조건이 아닌 것은 무엇인가요?',ARRAY['K4-1-u5-X31']::text[],false,'{"seq":6,"concept":"K4-1-u5-C37","difficulty":2,"kind":"mc","stem":"잘 쓴 독서 감상문의 조건이 아닌 것은 무엇인가요?","options":[{"t":"책의 모든 장면을 빠짐없이 적었다","correct":true},{"t":"내용을 잘 나타내는 제목을 붙였다","mis":"K4-1-u5-X31"},{"t":"인상 깊은 장면을 까닭과 함께 썼다","mis":"K4-1-u5-X31"},{"t":"떠오른 생각이나 느낌을 자세히 썼다","mis":"K4-1-u5-X31"}],"explanation":["줄거리는?","간추려요.","빠짐없이는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#7','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C38',2,'mc','auto','「할머니가 젖은 종이배를 건네는 장면이 기억에 남았다.」를 더 좋게 고치는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X37']::text[],false,'{"seq":7,"concept":"K4-1-u5-C38","difficulty":2,"kind":"mc","stem":"「할머니가 젖은 종이배를 건네는 장면이 기억에 남았다.」를 더 좋게 고치는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"기억에 남은 까닭을 덧붙인다","correct":true},{"t":"이 문장을 지운다","mis":"K4-1-u5-X37"},{"t":"같은 문장을 한 번 더 쓴다","mis":"K4-1-u5-X37"},{"t":"장면을 다른 책의 장면으로 바꾼다","mis":"K4-1-u5-X37"}],"explanation":["장면은 있어요.","무엇이 빠졌나요?","까닭을 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#8','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C35',2,'mc','auto','유나의 감상문에서 끝 부분에 해당하는 문장은 무엇인가요?',ARRAY['K4-1-u5-X35']::text[],false,'{"seq":8,"concept":"K4-1-u5-C35","difficulty":2,"kind":"mc","stem":"유나의 감상문에서 끝 부분에 해당하는 문장은 무엇인가요?","options":[{"t":"⑤ 이제는 할 말이 있으면 용기를 내어 직접 건네 보겠다.","correct":true},{"t":"① 친구가 표지의 하얀 종이배가 예쁘다며 권해 주어 읽게 되었다.","mis":"K4-1-u5-X35"},{"t":"② 해오는 미안하다는 말을 못 하고 종이배에만 적어 띄운다.","mis":"K4-1-u5-X35"},{"t":"③ 할머니가 젖은 종이배를 건네는 장면이 가장 기억에 남았다.","mis":"K4-1-u5-X35"}],"explanation":["끝에는?","생각이나 느낌","다짐이에요."],"asset":{"type":"passage","lines":["① 친구가 표지의 하얀 종이배가 예쁘다며 권해 주어 읽게 되었다.","② 해오는 미안하다는 말을 못 하고 종이배에만 적어 띄운다.","③ 할머니가 젖은 종이배를 건네는 장면이 가장 기억에 남았다.","④ 나도 하고 싶은 말을 마음속에만 담아 둔 적이 있어서 뜨끔했기 때문이다.","⑤ 이제는 할 말이 있으면 용기를 내어 직접 건네 보겠다."],"title":"유나의 독서 감상문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#9','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C40',2,'mc','auto','같은 책을 읽은 친구와 인상 깊은 장면이 서로 달라요. 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u5-X39','K4-1-u5-X28']::text[],false,'{"seq":9,"concept":"K4-1-u5-C40","difficulty":2,"kind":"mc","stem":"같은 책을 읽은 친구와 인상 깊은 장면이 서로 달라요. 알맞은 생각은 무엇인가요?","options":[{"t":"마음에 남는 자리는 저마다 다를 수 있으니 친구가 고른 까닭을 들어 본다","correct":true},{"t":"내 장면과 다르면 친구가 틀린 것이다","mis":"K4-1-u5-X39"},{"t":"반 모두가 같은 장면을 골라야 한다","mis":"K4-1-u5-X39"},{"t":"까닭 없이 아무 장면이나 골라도 된다","mis":"K4-1-u5-X28"}],"explanation":["저마다 다를 수 있어요.","까닭을 들어요.","틀린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_basic#10','kor',4,1,'u5','L09','g4_1_kor_u5_L09_basic','lesson_basic','K4-1-u5-C36',3,'mc','auto','독서 감상문에서 문단을 나누기에 가장 알맞은 곳은 어디인가요?',ARRAY['K4-1-u5-X36']::text[],false,'{"seq":10,"concept":"K4-1-u5-C36","difficulty":3,"kind":"mc","stem":"독서 감상문에서 문단을 나누기에 가장 알맞은 곳은 어디인가요?","options":[{"t":"책의 내용을 다 쓰고 생각이나 느낌을 쓰기 시작하는 곳","correct":true},{"t":"문장이 세 개 모일 때마다","mis":"K4-1-u5-X36"},{"t":"인상 깊은 장면 문장과 그 까닭 문장 사이","mis":"K4-1-u5-X36"},{"t":"감상문을 다 쓸 때까지 나누지 않는다","mis":"K4-1-u5-X36"}],"explanation":["내용이 바뀌는 곳","책 이야기 → 내 마음","거기서 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#1','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C33',2,'mc','auto','친구가 「가장 얇은 책을 골라야 빨리 쓰지.」라고 했어요. 가장 알맞게 대답한 것은 무엇인가요?',ARRAY['K4-1-u5-X33']::text[],false,'{"seq":1,"concept":"K4-1-u5-C33","difficulty":2,"kind":"mc","stem":"친구가 「가장 얇은 책을 골라야 빨리 쓰지.」라고 했어요. 가장 알맞게 대답한 것은 무엇인가요?","options":[{"t":"「읽고 싶어지는 까닭이 있는 책을 골라야 마음에 남는 것이 생겨.」","correct":true},{"t":"「맞아. 얇은 책이 늘 가장 좋아.」","mis":"K4-1-u5-X33"},{"t":"「아무 책이나 눈 감고 고르면 돼.」","mis":"K4-1-u5-X33"},{"t":"「책은 고르지 말고 아무거나 받아야 해.」","mis":"K4-1-u5-X33"}],"explanation":["왜 읽고 싶나요?","마음에 남는 것","까닭이 있는 책"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#2','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C39',2,'mc','auto','인터뷰 형식으로 독서 감상문을 쓴다는 것은 어떤 뜻인가요?',ARRAY['K4-1-u5-X38','K4-1-u5-X30']::text[],false,'{"seq":2,"concept":"K4-1-u5-C39","difficulty":2,"kind":"mc","stem":"인터뷰 형식으로 독서 감상문을 쓴다는 것은 어떤 뜻인가요?","options":[{"t":"친구가 묻고 내가 답하며 책 이야기와 느낌을 나눈다","correct":true},{"t":"인터뷰로 쓰면 생각이나 느낌은 빼야 한다","mis":"K4-1-u5-X38"},{"t":"인터뷰는 감상문이 될 수 없다","mis":"K4-1-u5-X38"},{"t":"인터뷰에는 책 이야기를 넣지 않는다","mis":"K4-1-u5-X30"}],"explanation":["묻고 답해요.","책 이야기와 느낌","형식만 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#3','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C35',3,'mc','auto','유나의 감상문을 처음 · 가운데 · 끝으로 바르게 가른 것은 무엇인가요?',ARRAY['K4-1-u5-X35']::text[],false,'{"seq":3,"concept":"K4-1-u5-C35","difficulty":3,"kind":"mc","stem":"유나의 감상문을 처음 · 가운데 · 끝으로 바르게 가른 것은 무엇인가요?","options":[{"t":"처음 ① / 가운데 ②~④ / 끝 ⑤","correct":true},{"t":"처음 ①② / 가운데 ③ / 끝 ④⑤","mis":"K4-1-u5-X35"},{"t":"처음 ⑤ / 가운데 ②~④ / 끝 ①","mis":"K4-1-u5-X35"},{"t":"처음 ①~③ / 가운데 ④ / 끝 ⑤","mis":"K4-1-u5-X35"}],"explanation":["읽게 된 까닭","내용과 장면","느낌"],"asset":{"type":"passage","lines":["① 친구가 표지의 하얀 종이배가 예쁘다며 권해 주어 읽게 되었다.","② 해오는 미안하다는 말을 못 하고 종이배에만 적어 띄운다.","③ 할머니가 젖은 종이배를 건네는 장면이 가장 기억에 남았다.","④ 나도 하고 싶은 말을 마음속에만 담아 둔 적이 있어서 뜨끔했기 때문이다.","⑤ 이제는 할 말이 있으면 용기를 내어 직접 건네 보겠다."],"title":"유나의 독서 감상문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#4','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C37',3,'mc','auto','유나의 감상문에서 잘 쓴 점은 무엇인가요?',ARRAY['K4-1-u5-X31','K4-1-u5-X25','K4-1-u5-X29']::text[],false,'{"seq":4,"concept":"K4-1-u5-C37","difficulty":3,"kind":"mc","stem":"유나의 감상문에서 잘 쓴 점은 무엇인가요?","options":[{"t":"인상 깊은 장면을 내 경험과 이어 까닭을 썼다","correct":true},{"t":"책의 모든 장면을 빠짐없이 적었다","mis":"K4-1-u5-X31"},{"t":"책 제목을 그대로 감상문 제목으로 썼다","mis":"K4-1-u5-X25"},{"t":"생각이나 느낌을 쓰지 않았다","mis":"K4-1-u5-X29"}],"explanation":["③과 ④를 봐요.","장면과 까닭","경험과 이었어요."],"asset":{"type":"passage","lines":["① 친구가 표지의 하얀 종이배가 예쁘다며 권해 주어 읽게 되었다.","② 해오는 미안하다는 말을 못 하고 종이배에만 적어 띄운다.","③ 할머니가 젖은 종이배를 건네는 장면이 가장 기억에 남았다.","④ 나도 하고 싶은 말을 마음속에만 담아 둔 적이 있어서 뜨끔했기 때문이다.","⑤ 이제는 할 말이 있으면 용기를 내어 직접 건네 보겠다."],"title":"유나의 독서 감상문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#5','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C38',3,'mc','auto','점검표의 「떠오른 생각이나 느낌을 자세히 썼다」에 「아니요」가 나왔어요. 알맞게 한 것은 무엇인가요?',ARRAY['K4-1-u5-X37','K4-1-u5-X31']::text[],false,'{"seq":5,"concept":"K4-1-u5-C38","difficulty":3,"kind":"mc","stem":"점검표의 「떠오른 생각이나 느낌을 자세히 썼다」에 「아니요」가 나왔어요. 알맞게 한 것은 무엇인가요?","options":[{"t":"책을 읽고 떠오른 생각이나 다짐을 덧붙여 고쳐 쓴다","correct":true},{"t":"「예」로 바꾸어 표시한다","mis":"K4-1-u5-X37"},{"t":"줄거리를 더 길게 쓴다","mis":"K4-1-u5-X31"},{"t":"제목만 바꾼다","mis":"K4-1-u5-X37"}],"explanation":["무엇이 빠졌나요?","생각이나 느낌","덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#6','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C40',3,'mc','auto','친구의 독서 감상문을 읽으면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X39','K4-1-u5-X23']::text[],false,'{"seq":6,"concept":"K4-1-u5-C40","difficulty":3,"kind":"mc","stem":"친구의 독서 감상문을 읽으면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"내가 미처 보지 못한 장면이나 생각을 새로 알게 된다","correct":true},{"t":"내 감상문을 친구 것과 똑같이 고쳐야 한다","mis":"K4-1-u5-X39"},{"t":"친구와 다르게 느낀 내가 틀렸음을 알게 된다","mis":"K4-1-u5-X39"},{"t":"책을 다시 읽지 않아도 된다","mis":"K4-1-u5-X23"}],"explanation":["저마다 다른 감상","못 본 장면","새로 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#7','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C34',3,'mc','auto','감상문을 쓰기 전에 쓸 내용을 항목별로 정리해 두는 까닭은 무엇인가요?',ARRAY['K4-1-u5-X34']::text[],false,'{"seq":7,"concept":"K4-1-u5-C34","difficulty":3,"kind":"mc","stem":"감상문을 쓰기 전에 쓸 내용을 항목별로 정리해 두는 까닭은 무엇인가요?","options":[{"t":"쓸 내용을 미리 갈라 두면 처음 · 가운데 · 끝에 맞게 옮겨 쓸 수 있어서","correct":true},{"t":"정리하면 감상문을 쓸 필요가 없어서","mis":"K4-1-u5-X34"},{"t":"항목은 아무 칸에 적어도 되어서","mis":"K4-1-u5-X34"},{"t":"정리한 내용은 모두 지우고 새로 써야 해서","mis":"K4-1-u5-X34"}],"explanation":["미리 갈라 두면","흐름대로","옮겨 쓰기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#8','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C35',4,'essay','teacher','독서 감상문의 처음 · 가운데 · 끝에 각각 무엇을 쓰는지 쓰고, 문단은 어디에서 나누는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u5-C35","difficulty":4,"kind":"essay","stem":"독서 감상문의 처음 · 가운데 · 끝에 각각 무엇을 쓰는지 쓰고, 문단은 어디에서 나누는지 쓰세요.","answer_guide":{"answer":"예: 처음에는 책을 읽게 된 까닭을 쓴다. 가운데에는 책의 내용과 인상 깊은 장면, 그 까닭을 쓴다. 끝에는 책을 읽고 떠오른 생각이나 느낌을 쓴다. 문단은 내용이 바뀌는 자리에서 나눈다.","scoring_points":["처음에 쓸 것을 썼는가","가운데와 끝에 쓸 것을 썼는가","문단 나누는 곳을 썼는가"]},"explanation":["처음","가운데","끝"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#9','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C38',4,'essay','teacher','「할머니가 젖은 종이배를 건네는 장면이 기억에 남았다.」를 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u5-C38","difficulty":4,"kind":"essay","stem":"「할머니가 젖은 종이배를 건네는 장면이 기억에 남았다.」를 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.","answer_guide":{"answer":"예: 할머니가 젖은 종이배를 건네는 장면이 기억에 남았다. 띄워 보낸 말은 닿지 않는다는 것을 깨달았기 때문이다. — 장면만 있고 기억에 남은 까닭이 빠져 있어서 까닭을 덧붙였다.","scoring_points":["고쳐 쓴 문장을 썼는가","기억에 남은 까닭을 덧붙였는가","고친 까닭을 썼는가"]},"explanation":["장면","빠진 것","덧붙여요."],"asset":{"type":"passage","lines":["① 바닷가 마을 해오는 하고 싶은 말을 꺼내는 일이 서툴렀다.","② 이사 간 보라에게 미안하다는 말을 끝내 하지 못했다.","③ 해오는 그 말을 종이배에 적어 날마다 냇물에 띄웠다.","④ 냇가 할머니가 젖은 종이배를 건네며 말했다.","⑤ \"말은 띄우는 게 아니라 건네는 거란다.\"","⑥ 해오는 보라에게 전화를 걸어 처음으로 미안하다고 말했다."],"title":"종이배 우체부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L09_challenge#10','kor',4,1,'u5','L09','g4_1_kor_u5_L09_challenge','lesson_challenge','K4-1-u5-C39',4,'essay','teacher','「종이배 우체부」의 감상을 편지 형식으로 쓰려고 해요. 누구에게 쓸지 정하고, 편지의 첫 두 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u5-C39","difficulty":4,"kind":"essay","stem":"「종이배 우체부」의 감상을 편지 형식으로 쓰려고 해요. 누구에게 쓸지 정하고, 편지의 첫 두 문장을 쓰세요.","answer_guide":{"answer":"예: 해오에게 쓴다. 「해오야, 종이배에 적은 말을 날마다 띄웠다는 이야기를 읽었어. 나도 하고 싶은 말을 마음속에만 담아 둔 적이 있어서 네 마음을 알 것 같아.」","scoring_points":["편지를 받을 사람을 정했는가","책 이야기를 담았는가","내 생각이나 느낌을 담았는가"]},"explanation":["누구에게?","책 이야기","내 마음"],"asset":{"type":"passage","lines":["① 바닷가 마을 해오는 하고 싶은 말을 꺼내는 일이 서툴렀다.","② 이사 간 보라에게 미안하다는 말을 끝내 하지 못했다.","③ 해오는 그 말을 종이배에 적어 날마다 냇물에 띄웠다.","④ 냇가 할머니가 젖은 종이배를 건네며 말했다.","⑤ \"말은 띄우는 게 아니라 건네는 거란다.\"","⑥ 해오는 보라에게 전화를 걸어 처음으로 미안하다고 말했다."],"title":"종이배 우체부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#1','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C41',1,'mc','auto','여행한 곳을 소개할 때 넣을 내용으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X40']::text[],false,'{"seq":1,"concept":"K4-1-u5-C41","difficulty":1,"kind":"mc","stem":"여행한 곳을 소개할 때 넣을 내용으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"그날 내가 입은 옷의 값","correct":true},{"t":"그곳이 어디에 있는지","mis":"K4-1-u5-X40"},{"t":"가서 볼 만한 것","mis":"K4-1-u5-X40"},{"t":"그곳에서 인상 깊었던 일","mis":"K4-1-u5-X40"}],"explanation":["듣는 친구가 궁금한 것","가 보고 싶게","옷값은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#2','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C42',1,'mc','auto','친구의 독서 감상문에 다는 댓글로 친구를 배려한 것은 무엇인가요?',ARRAY['K4-1-u5-X41','K4-1-u5-X42']::text[],false,'{"seq":2,"concept":"K4-1-u5-C42","difficulty":1,"kind":"mc","stem":"친구의 독서 감상문에 다는 댓글로 친구를 배려한 것은 무엇인가요?","options":[{"t":"「인상 깊은 장면을 까닭까지 써서 잘 이해됐어.」","correct":true},{"t":"「글이 재미없어서 끝까지 못 읽겠어.」","mis":"K4-1-u5-X41"},{"t":"「이 책은 내가 먼저 읽었어.」","mis":"K4-1-u5-X42"},{"t":"「글씨가 이상해.」","mis":"K4-1-u5-X41"}],"explanation":["읽는 친구의 마음","칭찬과 격려","배려하는 댓글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#3','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C48',1,'mc','auto','순우리말 「도란도란」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X46']::text[],false,'{"seq":3,"concept":"K4-1-u5-C48","difficulty":1,"kind":"mc","stem":"순우리말 「도란도란」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"여럿이 나직한 목소리로 정답게 이야기하는 모양","correct":true},{"t":"비가 세차게 쏟아지는 모양","mis":"K4-1-u5-X46"},{"t":"혼자 큰 소리로 우는 모양","mis":"K4-1-u5-X46"},{"t":"발을 구르며 뛰는 모양","mis":"K4-1-u5-X46"}],"explanation":["소리와 느낌","정답게","이야기하는 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#4','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C47',1,'mc','auto','발표를 들을 때 지켜야 할 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X19','K4-1-u5-X45']::text[],false,'{"seq":4,"concept":"K4-1-u5-C47","difficulty":1,"kind":"mc","stem":"발표를 들을 때 지켜야 할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"잘 이해되지 않은 것은 발표가 끝난 뒤에 묻는다","correct":true},{"t":"궁금한 것이 생기면 바로 끼어들어 묻는다","mis":"K4-1-u5-X19"},{"t":"중요한 내용도 적지 않고 흘려듣는다","mis":"K4-1-u5-X45"},{"t":"발표하는 친구 대신 창밖을 본다","mis":"K4-1-u5-X19"}],"explanation":["언제 물을까요?","끝난 뒤에","끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#5','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C43',2,'match','auto','친구의 감상문 내용과 어울리는 댓글을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u5-C43","difficulty":2,"kind":"match","stem":"친구의 감상문 내용과 어울리는 댓글을 알맞게 이으세요.","pairs":[{"l":"나도 하고 싶은 말을 마음에만 담아 둔 적이 있다","r":"네 경험을 함께 써서 마음에 더 와닿았어."},{"l":"바닷가 마을 그림이 아름다웠다","r":"네 글을 읽고 나도 그 그림이 보고 싶어졌어."},{"l":"해오가 먼저 전화를 걸어 놀랐다","r":"먼저 건네는 용기, 나도 배우고 싶어."}],"mis":"K4-1-u5-X42","explanation":["친구가 무엇을 썼나요?","그에 맞게","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#6','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C44',2,'mc','auto','이 단원에서 배운 것을 실천하는 활동이 아닌 것은 무엇인가요?',ARRAY['K4-1-u5-X43']::text[],false,'{"seq":6,"concept":"K4-1-u5-C44","difficulty":2,"kind":"mc","stem":"이 단원에서 배운 것을 실천하는 활동이 아닌 것은 무엇인가요?","options":[{"t":"발표를 잘하는 친구에게만 발표를 맡긴다","correct":true},{"t":"여행한 곳을 조사해 친구들 앞에서 소개한다","mis":"K4-1-u5-X43"},{"t":"독서 감상문을 올리고 서로 댓글을 쓴다","mis":"K4-1-u5-X43"},{"t":"책 전시회를 열어 읽고 싶은 책을 고른다","mis":"K4-1-u5-X43"}],"explanation":["말로 전하기","글로 전하기","모두 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
