INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#8','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C49',2,'mc','auto','「ㅅ」이 받침 자리에 쓰인 글자는 무엇인가요?',ARRAY['K4-1-u5-X48']::text[],false,'{"seq":8,"concept":"K4-1-u5-C49","difficulty":2,"kind":"mc","stem":"「ㅅ」이 받침 자리에 쓰인 글자는 무엇인가요?","options":[{"t":"앗","correct":true},{"t":"소","mis":"K4-1-u5-X48"},{"t":"사","mis":"K4-1-u5-X48"},{"t":"슴","mis":"K4-1-u5-X48"}],"explanation":["받침은 아래에","씨앗","앗이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#9','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C45',2,'mc','auto','「나의 소원 세 가지」를 뽑아 1분 동안 말할 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X44','K4-1-u5-X02']::text[],false,'{"seq":9,"concept":"K4-1-u5-C45","difficulty":2,"kind":"mc","stem":"「나의 소원 세 가지」를 뽑아 1분 동안 말할 때 알맞은 것은 무엇인가요?","options":[{"t":"세 가지 소원을 차례대로 까닭과 함께 말한다","correct":true},{"t":"주제와 상관없이 생각나는 것을 모두 말한다","mis":"K4-1-u5-X44"},{"t":"1분이 될 때까지 같은 말을 되풀이한다","mis":"K4-1-u5-X44"},{"t":"주제가 어려우면 말하지 않고 넘긴다","mis":"K4-1-u5-X02"}],"explanation":["뽑은 주제","차례대로","까닭과 함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_basic#10','kor',4,1,'u5','L11','g4_1_kor_u5_L11_basic','lesson_basic','K4-1-u5-C46',3,'mc','auto','「말과 글로 전하는 생각」 단원에서 배운 것을 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u5-X49','K4-1-u5-X01']::text[],false,'{"seq":10,"concept":"K4-1-u5-C46","difficulty":3,"kind":"mc","stem":"「말과 글로 전하는 생각」 단원에서 배운 것을 바르게 정리한 것은 무엇인가요?","options":[{"t":"발표로 말을 하고 감상문으로 글을 써서 생각을 전하며, 다른 사람의 생각에도 귀 기울인다","correct":true},{"t":"말로 전하는 것만 중요하고 글은 상관없다","mis":"K4-1-u5-X49"},{"t":"내 생각을 전하기만 하면 남의 생각은 듣지 않아도 된다","mis":"K4-1-u5-X49"},{"t":"발표와 감상문은 생각을 전하는 일과 관련이 없다","mis":"K4-1-u5-X01"}],"explanation":["말로","글로","귀 기울이기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#1','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C42',2,'mc','auto','「인상 깊은 장면이 없어서 별로야.」라는 댓글을 배려하는 댓글로 고친 것은 무엇인가요?',ARRAY['K4-1-u5-X41','K4-1-u5-X20','K4-1-u5-X42']::text[],false,'{"seq":1,"concept":"K4-1-u5-C42","difficulty":2,"kind":"mc","stem":"「인상 깊은 장면이 없어서 별로야.」라는 댓글을 배려하는 댓글로 고친 것은 무엇인가요?","options":[{"t":"「책 이야기를 잘 간추렸어. 인상 깊은 장면도 써 주면 네 마음이 더 잘 보일 것 같아.」","correct":true},{"t":"「별로야. 다시 써.」","mis":"K4-1-u5-X41"},{"t":"「좋아.」","mis":"K4-1-u5-X20"},{"t":"「나는 그 책 안 읽어 봤어.」","mis":"K4-1-u5-X42"}],"explanation":["잘한 점 먼저","보탤 점은 부드럽게","격려해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#2','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C48',2,'mc','auto','순우리말을 알맞게 쓴 문장은 무엇인가요?',ARRAY['K4-1-u5-X46']::text[],false,'{"seq":2,"concept":"K4-1-u5-C48","difficulty":2,"kind":"mc","stem":"순우리말을 알맞게 쓴 문장은 무엇인가요?","options":[{"t":"할머니는 처음 본 나에게도 살갑게 말을 건네셨다.","correct":true},{"t":"얼음물이 아주 살갑게 차가웠다.","mis":"K4-1-u5-X46"},{"t":"비가 도란도란 세차게 쏟아졌다.","mis":"K4-1-u5-X46"},{"t":"빈 상자가 옹골지게 텅 비어 있었다.","mis":"K4-1-u5-X46"}],"explanation":["뜻을 넣어 읽어요.","다정하게","살갑게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#3','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C41',3,'mc','auto','시우의 소개 원고에 더 넣어야 할 부분은 무엇인가요?',ARRAY['K4-1-u5-X16','K4-1-u5-X40']::text[],false,'{"seq":3,"concept":"K4-1-u5-C41","difficulty":3,"kind":"mc","stem":"시우의 소개 원고에 더 넣어야 할 부분은 무엇인가요?","options":[{"t":"소개한 내용을 간단히 정리하고 인사하는 끝맺는 말","correct":true},{"t":"어디를 소개할지 알리는 시작하는 말","mis":"K4-1-u5-X16"},{"t":"그날 먹은 점심의 값","mis":"K4-1-u5-X40"},{"t":"수목원 입구 계단의 개수","mis":"K4-1-u5-X40"}],"explanation":["①은 시작하는 말","②~④는 설명하는 말","무엇이 빠졌나요?"],"asset":{"type":"passage","lines":["① 지금부터 제가 다녀온 솔바람 수목원을 소개하겠습니다.","② 솔바람 수목원은 우리 고장 북쪽 산자락에 있습니다.","③ 키 큰 소나무 숲길과 작은 연못이 볼거리입니다.","④ 연못가에서 다람쥐가 도토리를 물고 달려가는 모습을 보았습니다."],"title":"시우의 소개 원고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#4','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C47',3,'mc','auto','친구의 발표 내용이 길고 중요할 때 알맞은 듣기 태도는 무엇인가요?',ARRAY['K4-1-u5-X45','K4-1-u5-X19']::text[],false,'{"seq":4,"concept":"K4-1-u5-C47","difficulty":3,"kind":"mc","stem":"친구의 발표 내용이 길고 중요할 때 알맞은 듣기 태도는 무엇인가요?","options":[{"t":"중요한 내용을 적으면서 듣는다","correct":true},{"t":"적는 것은 딴짓이니 하지 않는다","mis":"K4-1-u5-X45"},{"t":"발표 도중에 다시 말해 달라고 끼어든다","mis":"K4-1-u5-X19"},{"t":"길면 끝까지 듣지 않는다","mis":"K4-1-u5-X19"}],"explanation":["잊기 쉬운 내용","적으며","끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#5','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C49',3,'mc','auto','ㅅ과 ㅆ을 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X48']::text[],false,'{"seq":5,"concept":"K4-1-u5-C49","difficulty":3,"kind":"mc","stem":"ㅅ과 ㅆ을 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"놓이는 자리에 따라 모양과 크기를 맞추어 쓴다","correct":true},{"t":"어느 자리에서나 똑같은 모양과 크기로 쓴다","mis":"K4-1-u5-X48"},{"t":"받침의 ㅅ은 늘 가장 크게 쓴다","mis":"K4-1-u5-X48"},{"t":"ㅆ은 두 ㅅ을 서로 멀리 떨어뜨려 쓴다","mis":"K4-1-u5-X48"}],"explanation":["소 · 사 · 앗","자리마다 달라요.","맞추어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#6','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C43',3,'mc','auto','친구가 감상문에 「나도 물건을 쉽게 버린 적이 있다」라고 썼어요. 어울리는 댓글은 무엇인가요?',ARRAY['K4-1-u5-X42','K4-1-u5-X41']::text[],false,'{"seq":6,"concept":"K4-1-u5-C43","difficulty":3,"kind":"mc","stem":"친구가 감상문에 「나도 물건을 쉽게 버린 적이 있다」라고 썼어요. 어울리는 댓글은 무엇인가요?","options":[{"t":"「네 경험을 함께 써서 와닿았어. 나도 고쳐 쓸 물건이 있는지 살펴볼래.」","correct":true},{"t":"「밤에만 여는 도서관이 신비로웠겠다.」","mis":"K4-1-u5-X42"},{"t":"「네 글씨가 더 예뻤으면 좋겠어.」","mis":"K4-1-u5-X41"},{"t":"「나는 물건을 버린 적 없어.」","mis":"K4-1-u5-X42"}],"explanation":["친구가 쓴 내용","경험","그에 맞게 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#7','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C48',3,'mc','auto','「옹골지다」를 알맞게 쓴 문장은 무엇인가요?',ARRAY['K4-1-u5-X46','K4-1-u5-X47']::text[],false,'{"seq":7,"concept":"K4-1-u5-C48","difficulty":3,"kind":"mc","stem":"「옹골지다」를 알맞게 쓴 문장은 무엇인가요?","options":[{"t":"여름내 가꾼 고추가 옹골지게 여물었다.","correct":true},{"t":"얇은 종이가 옹골지게 찢어졌다.","mis":"K4-1-u5-X46"},{"t":"바람이 옹골지게 불어 시원했다.","mis":"K4-1-u5-X46"},{"t":"옹골지다는 옛날 말이라 이제 쓰지 않는다.","mis":"K4-1-u5-X47"}],"explanation":["실속 있게 꽉 찬","여문 고추","뜻에 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#8','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C41',4,'essay','teacher','가 본 곳 한 곳을 정해 시작하는 말 · 설명하는 말 · 끝맺는 말로 소개하는 원고를 쓰세요. 설명하는 말에는 위치와 볼거리, 인상 깊었던 일을 넣으세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u5-C41","difficulty":4,"kind":"essay","stem":"가 본 곳 한 곳을 정해 시작하는 말 · 설명하는 말 · 끝맺는 말로 소개하는 원고를 쓰세요. 설명하는 말에는 위치와 볼거리, 인상 깊었던 일을 넣으세요.","answer_guide":{"answer":"예: 지금부터 제가 다녀온 바닷가 마을을 소개하겠습니다. 그곳은 우리 고장 동쪽 끝에 있습니다. 하얀 등대와 넓은 모래밭이 볼거리입니다. 해 질 녘 갈매기 떼가 한꺼번에 날아오르는 모습이 가장 인상 깊었습니다. 지금까지 바닷가 마을을 소개했습니다. 들어 주셔서 고맙습니다.","scoring_points":["시작 · 설명 · 끝맺는 말을 차례대로 썼는가","위치와 볼거리를 넣었는가","인상 깊었던 일을 넣었는가"]},"explanation":["어디를?","위치 · 볼거리 · 인상 깊은 일","정리하고 인사"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#9','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C42',4,'essay','teacher','친구의 독서 감상문에 칭찬과 격려를 담은 댓글을 쓰고, 그렇게 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u5-C42","difficulty":4,"kind":"essay","stem":"친구의 독서 감상문에 칭찬과 격려를 담은 댓글을 쓰고, 그렇게 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 「할머니 장면을 네 경험과 이어 써서 마음이 잘 느껴졌어. 다음에는 해오에게 편지를 써 봐도 재미있겠다.」 — 잘한 점을 구체적으로 칭찬하고 보탤 점을 부드럽게 말하면 친구가 기분 좋게 다음 글을 쓸 수 있기 때문이다.","scoring_points":["잘한 점을 구체적으로 칭찬했는가","격려나 보탤 점을 부드럽게 썼는가","까닭을 썼는가"]},"explanation":["잘한 점","격려","읽는 친구의 마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_L11_challenge#10','kor',4,1,'u5','L11','g4_1_kor_u5_L11_challenge','lesson_challenge','K4-1-u5-C46',4,'essay','teacher','이 단원에서 배운 것을 생활에서 어떻게 실천할지 말로 전하기 하나, 글로 전하기 하나를 골라 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u5-C46","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 것을 생활에서 어떻게 실천할지 말로 전하기 하나, 글로 전하기 하나를 골라 쓰세요.","answer_guide":{"answer":"예: 말로는 모둠 발표 때 듣는 친구들을 바라보며 알맞은 빠르기로 말하겠다. 글로는 이번 달에 읽은 책으로 독서 감상문을 써서 학급 누리집에 올리고 친구들 글에 칭찬 댓글을 달겠다.","scoring_points":["말로 전하기 실천을 썼는가","글로 전하기 실천을 썼는가","배운 방법을 넣어 구체적으로 썼는가"]},"explanation":["말로","글로","구체적으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#1','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C22',1,'mc','auto','책을 읽고 생각이나 느낌을 쓴 글을 무엇이라고 하나요?',ARRAY['K4-1-u5-X16','K4-1-u5-X15','K4-1-u5-X22']::text[],false,'{"seq":1,"concept":"K4-1-u5-C22","difficulty":1,"kind":"mc","stem":"책을 읽고 생각이나 느낌을 쓴 글을 무엇이라고 하나요?","options":[{"t":"독서 감상문","correct":true},{"t":"발표 원고","mis":"K4-1-u5-X16"},{"t":"조사 표","mis":"K4-1-u5-X15"},{"t":"안내문","mis":"K4-1-u5-X22"}],"explanation":["책을 읽고","내 마음을 쓴 글","독서 감상문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#2','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C8',1,'mc','auto','자신 있게 발표하는 방법으로 알맞은 것을 고르세요.',ARRAY['K4-1-u5-X08','K4-1-u5-X09','K4-1-u5-X10']::text[],false,'{"seq":2,"concept":"K4-1-u5-C8","difficulty":1,"kind":"mc","stem":"자신 있게 발표하는 방법으로 알맞은 것을 고르세요.","options":[{"t":"알맞은 빠르기로 또박또박 말한다","correct":true},{"t":"종이에 쓴 것만 내려다보며 읽는다","mis":"K4-1-u5-X08"},{"t":"가장 큰 소리로 소리친다","mis":"K4-1-u5-X09"},{"t":"최대한 빨리 말하고 들어간다","mis":"K4-1-u5-X10"}],"explanation":["빠르기","또박또박","알맞게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#3','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C14',1,'mc','auto','발표 자료로 가장 믿을 만한 것은 무엇인가요?',ARRAY['K4-1-u5-X13']::text[],false,'{"seq":3,"concept":"K4-1-u5-C14","difficulty":1,"kind":"mc","stem":"발표 자료로 가장 믿을 만한 것은 무엇인가요?","options":[{"t":"누가 만들었는지 분명한 누리집의 자료","correct":true},{"t":"누가 썼는지 모르는 짧은 댓글","mis":"K4-1-u5-X13"},{"t":"친구가 들었다는 소문","mis":"K4-1-u5-X13"},{"t":"설명 없이 제목만 있는 그림 한 장","mis":"K4-1-u5-X13"}],"explanation":["누가 만들었나요?","분명한 곳","믿을 만해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#4','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C17',1,'mc','auto','「짱뚱어를 소개합니다」의 ①은 발표의 어느 부분인가요?',ARRAY['K4-1-u5-X16']::text[],false,'{"seq":4,"concept":"K4-1-u5-C17","difficulty":1,"kind":"mc","stem":"「짱뚱어를 소개합니다」의 ①은 발표의 어느 부분인가요?","options":[{"t":"시작하는 말","correct":true},{"t":"설명하는 말","mis":"K4-1-u5-X16"},{"t":"끝맺는 말","mis":"K4-1-u5-X16"},{"t":"듣는 사람의 질문","mis":"K4-1-u5-X16"}],"explanation":["처음 하는 말","무엇을 발표할지","시작하는 말이에요."],"asset":{"type":"passage","lines":["① 안녕하세요? 지금부터 갯벌에 사는 물고기 짱뚱어를 소개하겠습니다.","② 짱뚱어는 눈이 머리 위로 툭 튀어나와 있습니다. (어린이 백과사전)","③ 가슴지느러미로 진흙 위를 기어 다니며 아주 작은 먹이를 먹습니다.","④ 갯벌이 줄어들면서 짱뚱어가 살 곳도 줄고 있습니다.","⑤ 지금까지 짱뚱어의 생김새와 먹이, 사는 곳을 알아보았습니다.","들어 주셔서 고맙습니다."],"title":"짱뚱어를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#5','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C24',1,'mc','auto','독서 감상문에 쓰지 않아도 되는 것은 무엇인가요?',ARRAY['K4-1-u5-X24']::text[],false,'{"seq":5,"concept":"K4-1-u5-C24","difficulty":1,"kind":"mc","stem":"독서 감상문에 쓰지 않아도 되는 것은 무엇인가요?","options":[{"t":"책을 산 가게의 전화번호","correct":true},{"t":"책을 읽은 까닭","mis":"K4-1-u5-X24"},{"t":"인상 깊은 장면","mis":"K4-1-u5-X24"},{"t":"생각이나 느낌","mis":"K4-1-u5-X24"}],"explanation":["들어갈 내용","전화번호?","쓰지 않아도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#6','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C23',1,'mc','auto','독서 감상문을 쓰는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X23','K4-1-u5-X22']::text[],false,'{"seq":6,"concept":"K4-1-u5-C23","difficulty":1,"kind":"mc","stem":"독서 감상문을 쓰는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"내가 느낀 것을 다른 사람과 나누려고","correct":true},{"t":"책을 빨리 읽으려고","mis":"K4-1-u5-X23"},{"t":"줄거리를 외우려고","mis":"K4-1-u5-X22"},{"t":"책을 다시 안 읽으려고","mis":"K4-1-u5-X23"}],"explanation":["누구와?","나누려고","느낌을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#7','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C35',1,'mc','auto','독서 감상문의 끝 부분에 쓰기 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X35','K4-1-u5-X26']::text[],false,'{"seq":7,"concept":"K4-1-u5-C35","difficulty":1,"kind":"mc","stem":"독서 감상문의 끝 부분에 쓰기 알맞은 것은 무엇인가요?","options":[{"t":"책을 읽고 떠오른 생각이나 느낌","correct":true},{"t":"책을 읽게 된 까닭","mis":"K4-1-u5-X35"},{"t":"인물과 배경","mis":"K4-1-u5-X35"},{"t":"책의 쪽수","mis":"K4-1-u5-X26"}],"explanation":["끝에는","내 마음","생각이나 느낌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#8','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C47',1,'mc','auto','친구의 발표에서 잘 이해되지 않는 부분이 있을 때 알맞은 태도는 무엇인가요?',ARRAY['K4-1-u5-X19','K4-1-u5-X45']::text[],false,'{"seq":8,"concept":"K4-1-u5-C47","difficulty":1,"kind":"mc","stem":"친구의 발표에서 잘 이해되지 않는 부분이 있을 때 알맞은 태도는 무엇인가요?","options":[{"t":"발표가 끝난 뒤에 질문한다","correct":true},{"t":"발표 도중에 큰 소리로 묻는다","mis":"K4-1-u5-X19"},{"t":"그냥 넘기고 잊는다","mis":"K4-1-u5-X19"},{"t":"적는 것은 딴짓이니 손을 놓고 듣는다","mis":"K4-1-u5-X45"}],"explanation":["언제?","끝난 뒤에","질문해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#9','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C3',2,'mc','auto','인상 깊은 장면으로 고를 만한 것은 무엇인가요?',ARRAY['K4-1-u5-X03']::text[],false,'{"seq":9,"concept":"K4-1-u5-C3","difficulty":2,"kind":"mc","stem":"인상 깊은 장면으로 고를 만한 것은 무엇인가요?","options":[{"t":"인물의 마음이 잘 드러나 내 마음도 움직인 장면","correct":true},{"t":"글자 수가 가장 많은 장면","mis":"K4-1-u5-X03"},{"t":"책의 맨 첫 쪽","mis":"K4-1-u5-X03"},{"t":"그림이 가장 작은 장면","mis":"K4-1-u5-X03"}],"explanation":["마음이 움직였나요?","인물의 마음","그 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#10','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C18',2,'mc','auto','「짱뚱어는 조간대 갯벌의 규조류를 섭취한다.」를 쉬운 말로 바꾼 것은 무엇인가요?',ARRAY['K4-1-u5-X17']::text[],false,'{"seq":10,"concept":"K4-1-u5-C18","difficulty":2,"kind":"mc","stem":"「짱뚱어는 조간대 갯벌의 규조류를 섭취한다.」를 쉬운 말로 바꾼 것은 무엇인가요?","options":[{"t":"「짱뚱어는 바닷물이 드나드는 갯벌에서 아주 작은 먹이를 먹습니다.」","correct":true},{"t":"「짱뚱어는 조간대 갯벌의 규조류를 섭취합니다.」","mis":"K4-1-u5-X17"},{"t":"「먹이는 자료에 나온 그대로입니다.」","mis":"K4-1-u5-X17"},{"t":"「짱뚱어의 먹이는 어려워서 말하지 않겠습니다.」","mis":"K4-1-u5-X17"}],"explanation":["어려운 말","조간대 · 규조류 · 섭취","쉬운 말로 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#11','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C16',2,'match','auto','짱뚱어 발표를 준비하며 알고 싶은 점과 찾은 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K4-1-u5-C16","difficulty":2,"kind":"match","stem":"짱뚱어 발표를 준비하며 알고 싶은 점과 찾은 내용을 알맞게 이으세요.","pairs":[{"l":"생김새","r":"눈이 머리 위로 튀어나와 있다"},{"l":"먹이","r":"진흙 위의 아주 작은 먹이"},{"l":"사는 곳","r":"바닷물이 드나드는 갯벌"}],"mis":"K4-1-u5-X15","explanation":["어떻게 생겼나?","무엇을 먹나?","어디에 사나?"],"asset":{"type":"passage","lines":["① 안녕하세요? 지금부터 갯벌에 사는 물고기 짱뚱어를 소개하겠습니다.","② 짱뚱어는 눈이 머리 위로 툭 튀어나와 있습니다. (어린이 백과사전)","③ 가슴지느러미로 진흙 위를 기어 다니며 아주 작은 먹이를 먹습니다.","④ 갯벌이 줄어들면서 짱뚱어가 살 곳도 줄고 있습니다.","⑤ 지금까지 짱뚱어의 생김새와 먹이, 사는 곳을 알아보았습니다.","들어 주셔서 고맙습니다."],"title":"짱뚱어를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#12','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C25',2,'mc','auto','「빨간 장화 한 짝」 감상문에 어울리는 제목으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X25']::text[],false,'{"seq":12,"concept":"K4-1-u5-C25","difficulty":2,"kind":"mc","stem":"「빨간 장화 한 짝」 감상문에 어울리는 제목으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「쪽지가 이어 준 마음」","correct":true},{"t":"「빨간 장화 한 짝」","mis":"K4-1-u5-X25"},{"t":"「놀이터」","mis":"K4-1-u5-X25"},{"t":"「사흘」","mis":"K4-1-u5-X25"}],"explanation":["글쓴이가 느낀 것","⑤를 봐요.","느낌이 드러나요."],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#13','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C38',2,'mc','auto','「리아가 쪽지를 붙이는 장면이 기억에 남았다.」를 더 좋게 고친 것은 무엇인가요?',ARRAY['K4-1-u5-X37']::text[],false,'{"seq":13,"concept":"K4-1-u5-C38","difficulty":2,"kind":"mc","stem":"「리아가 쪽지를 붙이는 장면이 기억에 남았다.」를 더 좋게 고친 것은 무엇인가요?","options":[{"t":"리아가 쪽지를 붙이는 장면이 기억에 남았다. 모르는 사람을 위해 애쓰는 모습이 멋졌기 때문이다.","correct":true},{"t":"이 문장을 지운다.","mis":"K4-1-u5-X37"},{"t":"리아가 쪽지를 붙이는 장면이 기억에 남았다. 리아가 쪽지를 붙이는 장면이 기억에 남았다.","mis":"K4-1-u5-X37"},{"t":"리아가 쪽지를 붙이는 일이 기억에 남았다.","mis":"K4-1-u5-X37"}],"explanation":["장면은 있어요.","빠진 것은?","까닭을 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#14','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C41',2,'mc','auto','가 본 곳을 소개할 때 설명하는 말에 넣기 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X40']::text[],false,'{"seq":14,"concept":"K4-1-u5-C41","difficulty":2,"kind":"mc","stem":"가 본 곳을 소개할 때 설명하는 말에 넣기 알맞은 것은 무엇인가요?","options":[{"t":"위치, 볼거리, 인상 깊었던 일","correct":true},{"t":"그날 입은 옷의 값","mis":"K4-1-u5-X40"},{"t":"함께 간 사람의 나이","mis":"K4-1-u5-X40"},{"t":"집에서 출발한 시각","mis":"K4-1-u5-X40"}],"explanation":["어디에?","무엇을?","인상 깊은 일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#15','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C48',2,'mc','auto','순우리말을 알맞게 쓴 문장을 고르세요.',ARRAY['K4-1-u5-X46']::text[],false,'{"seq":15,"concept":"K4-1-u5-C48","difficulty":2,"kind":"mc","stem":"순우리말을 알맞게 쓴 문장을 고르세요.","options":[{"t":"저녁마다 가족이 도란도란 이야기를 나눈다.","correct":true},{"t":"천둥이 도란도란 울렸다.","mis":"K4-1-u5-X46"},{"t":"얼음이 살갑게 차갑다.","mis":"K4-1-u5-X46"},{"t":"구멍 난 양말이 옹골지다.","mis":"K4-1-u5-X46"}],"explanation":["뜻을 넣어 봐요.","정답게 이야기","도란도란이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#16','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C10',2,'mc','auto','발표의 빠르기에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u5-X10','K4-1-u5-X08']::text[],false,'{"seq":16,"concept":"K4-1-u5-C10","difficulty":2,"kind":"mc","stem":"발표의 빠르기에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"너무 빠르면 알아듣기 어려우니 알맞은 빠르기로 말한다","correct":true},{"t":"빨리 말할수록 잘한 발표이다","mis":"K4-1-u5-X10"},{"t":"빠르기는 발표와 상관없다","mis":"K4-1-u5-X08"},{"t":"한 글자씩 아주 느리게 끊어 말해야 한다","mis":"K4-1-u5-X10"}],"explanation":["너무 빠르면?","알아듣기 어려워요.","알맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#17','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C9',3,'mc','auto','친구가 「자신감은 큰 목소리야. 무조건 소리쳐야 해.」라고 했어요. 바로잡는 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X09','K4-1-u5-X08']::text[],false,'{"seq":17,"concept":"K4-1-u5-C9","difficulty":3,"kind":"mc","stem":"친구가 「자신감은 큰 목소리야. 무조건 소리쳐야 해.」라고 했어요. 바로잡는 말로 알맞은 것은 무엇인가요?","options":[{"t":"「큰 목소리는 잘 들리게 하려는 거야. 무조건 소리치면 오히려 듣기 힘들어.」","correct":true},{"t":"「맞아. 크게 소리칠수록 잘한 발표야.」","mis":"K4-1-u5-X09"},{"t":"「아니야. 목소리는 작을수록 좋아.」","mis":"K4-1-u5-X09"},{"t":"「목소리는 발표에서 중요하지 않아.」","mis":"K4-1-u5-X08"}],"explanation":["크게 하는 까닭","소리치면?","잘 들리게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#18','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C14',3,'mc','auto','「짱뚱어는 하늘을 날 수 있대.」라는, 누가 썼는지 모르는 댓글을 보았어요. 발표에 쓰기 전에 할 일은 무엇인가요?',ARRAY['K4-1-u5-X13','K4-1-u5-X14']::text[],false,'{"seq":18,"concept":"K4-1-u5-C14","difficulty":3,"kind":"mc","stem":"「짱뚱어는 하늘을 날 수 있대.」라는, 누가 썼는지 모르는 댓글을 보았어요. 발표에 쓰기 전에 할 일은 무엇인가요?","options":[{"t":"믿을 만한 자료에서 같은 내용이 있는지 확인한다","correct":true},{"t":"재미있으니 그대로 쓴다","mis":"K4-1-u5-X13"},{"t":"출처를 「댓글」이라고만 쓰면 된다","mis":"K4-1-u5-X14"},{"t":"내용을 더 신기하게 바꾸어 쓴다","mis":"K4-1-u5-X13"}],"explanation":["누가 썼나요?","확인","믿을 만한 곳에서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#19','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C31',3,'mc','auto','다온이의 감상문을 고쳐 쓸 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X31','K4-1-u5-X29','K4-1-u5-X37']::text[],false,'{"seq":19,"concept":"K4-1-u5-C31","difficulty":3,"kind":"mc","stem":"다온이의 감상문을 고쳐 쓸 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"줄거리는 간추리고 인상 깊은 장면과 생각을 자세히 쓴다","correct":true},{"t":"줄거리를 더 자세히 늘인다","mis":"K4-1-u5-X31"},{"t":"「재미있었다.」를 지운다","mis":"K4-1-u5-X29"},{"t":"제목만 바꾼다","mis":"K4-1-u5-X37"}],"explanation":["줄거리가 길어요.","내 마음은?","간추리고 더해요."],"asset":{"type":"passage","lines":["거북이 산 너머 마을로 가는 짐을 맡았다.","첫째 날에는 언덕을 넘었다.","둘째 날에는 비가 와서 나뭇잎 아래에서 쉬었다.","셋째 날에는 냇물을 건넜다.","넷째 날에 마을에 도착해 짐을 건넸다.","재미있었다."],"title":"다온이의 독서 감상문 — 「느림보 거북 택배」를 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#20','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C35',3,'mc','auto','감상문 문장 카드 가, 나, 다를 처음 · 가운데 · 끝 차례로 바르게 놓은 것은 무엇인가요?',ARRAY['K4-1-u5-X35']::text[],false,'{"seq":20,"concept":"K4-1-u5-C35","difficulty":3,"kind":"mc","stem":"감상문 문장 카드 가, 나, 다를 처음 · 가운데 · 끝 차례로 바르게 놓은 것은 무엇인가요?","options":[{"t":"나 → 다 → 가","correct":true},{"t":"가 → 나 → 다","mis":"K4-1-u5-X35"},{"t":"다 → 가 → 나","mis":"K4-1-u5-X35"},{"t":"가 → 다 → 나","mis":"K4-1-u5-X35"}],"explanation":["처음은 읽은 까닭","가운데는 장면","끝은 다짐"],"asset":{"type":"passage","lines":["가 나도 맡은 일을 끝까지 해내고 싶다.","나 친구가 재미있다고 권해 주어 읽게 되었다.","다 거북이 비를 맞으면서도 짐을 지킨 장면이 기억에 남았다."],"title":"감상문 문장 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#21','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C42',3,'mc','auto','친구 감상문에 인상 깊은 장면의 까닭이 빠져 있어요. 배려하면서도 도움이 되는 댓글은 무엇인가요?',ARRAY['K4-1-u5-X41','K4-1-u5-X20','K4-1-u5-X42']::text[],false,'{"seq":21,"concept":"K4-1-u5-C42","difficulty":3,"kind":"mc","stem":"친구 감상문에 인상 깊은 장면의 까닭이 빠져 있어요. 배려하면서도 도움이 되는 댓글은 무엇인가요?","options":[{"t":"「장면을 잘 골랐어. 왜 기억에 남았는지도 써 주면 네 마음이 더 잘 보일 것 같아.」","correct":true},{"t":"「까닭도 없고 별로야.」","mis":"K4-1-u5-X41"},{"t":"「잘했어.」","mis":"K4-1-u5-X20"},{"t":"「나는 다른 장면이 좋던데.」","mis":"K4-1-u5-X42"}],"explanation":["잘한 점","보탤 점","부드럽게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#22','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C47',3,'mc','auto','발표를 들으며 적을 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X19','K4-1-u5-X45']::text[],false,'{"seq":22,"concept":"K4-1-u5-C47","difficulty":3,"kind":"mc","stem":"발표를 들으며 적을 때 알맞은 것은 무엇인가요?","options":[{"t":"중요하거나 잊기 쉬운 내용을 짧게 적는다","correct":true},{"t":"발표자의 말을 한 글자도 빼지 않고 받아 적느라 발표자를 보지 않는다","mis":"K4-1-u5-X19"},{"t":"적는 것은 딴짓이니 하지 않는다","mis":"K4-1-u5-X45"},{"t":"발표와 상관없는 그림을 그린다","mis":"K4-1-u5-X19"}],"explanation":["무엇을 적나요?","중요한 것","짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#23','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C8',4,'essay','teacher','발표가 걱정된다는 친구에게 자신 있게 발표하는 방법 세 가지를 알려 주는 말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u5-C8","difficulty":4,"kind":"essay","stem":"발표가 걱정된다는 친구에게 자신 있게 발표하는 방법 세 가지를 알려 주는 말을 쓰세요.","answer_guide":{"answer":"예: 첫째, 발표할 내용을 미리 찾아 정리하고 연습해. 둘째, 교실 뒤까지 들리는 알맞은 목소리 크기로 또박또박 말해. 셋째, 너무 빠르지 않게 말하며 듣는 친구들을 바라봐.","scoring_points":["미리 정리하고 연습한다고 썼는가","목소리 크기 · 빠르기를 썼는가","듣는 사람을 바라본다고 썼는가"]},"explanation":["준비","크기 · 빠르기","바라보기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#24','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C30',4,'essay','teacher','「빨간 장화 한 짝」 감상문에서 책 이야기를 쓴 문장과 글쓴이의 마음을 쓴 문장을 하나씩 찾아 번호를 쓰고, 두 가지가 함께 있어서 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u5-C30","difficulty":4,"kind":"essay","stem":"「빨간 장화 한 짝」 감상문에서 책 이야기를 쓴 문장과 글쓴이의 마음을 쓴 문장을 하나씩 찾아 번호를 쓰고, 두 가지가 함께 있어서 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 책 이야기는 ②(리아가 장화 한 짝을 줍는다), 글쓴이의 마음은 ⑥(나도 주인을 찾아 주려고 애써야겠다)이다. 두 가지가 함께 있어 읽는 사람이 무슨 이야기인지 알면서 글쓴이의 감동도 나눌 수 있다.","scoring_points":["책 이야기 문장을 바르게 찾았는가","마음을 쓴 문장을 바르게 찾았는가","함께 있어서 좋은 점을 썼는가"]},"explanation":["②나 ③","⑤나 ⑥","함께라서"],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_a#25','kor',4,1,'u5','','g4_1_kor_u5_review_a','unit_review','K4-1-u5-C42',4,'essay','teacher','「빨간 장화 한 짝」 감상문을 읽고 글쓴이에게 칭찬과 격려를 담은 댓글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u5-C42","difficulty":4,"kind":"essay","stem":"「빨간 장화 한 짝」 감상문을 읽고 글쓴이에게 칭찬과 격려를 담은 댓글을 쓰세요.","answer_guide":{"answer":"예: 「쪽지 아래 글씨를 발견한 장면을 까닭과 함께 써서 나도 마음이 따뜻해졌어. 다음에는 리아에게 편지를 쓰는 형식으로도 써 보면 좋겠어.」","scoring_points":["잘한 점을 구체적으로 칭찬했는가","격려나 보탤 점을 부드럽게 썼는가","감상문 내용에 맞는 댓글인가"]},"explanation":["잘한 점","격려","글 내용에 맞게"],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#1','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C1',1,'mc','auto','이 단원에서 말로 생각을 전하는 방법으로 배운 것은 무엇인가요?',ARRAY['K4-1-u5-X01']::text[],false,'{"seq":1,"concept":"K4-1-u5-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 말로 생각을 전하는 방법으로 배운 것은 무엇인가요?","options":[{"t":"자신 있게 발표하기","correct":true},{"t":"받아쓰기","mis":"K4-1-u5-X01"},{"t":"그림일기 그리기","mis":"K4-1-u5-X01"},{"t":"노래 부르기","mis":"K4-1-u5-X01"}],"explanation":["말로 전하기","친구들 앞에서","발표하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#2','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C9',1,'mc','auto','발표할 때 목소리를 크게 하는 까닭은 무엇인가요?',ARRAY['K4-1-u5-X09','K4-1-u5-X10']::text[],false,'{"seq":2,"concept":"K4-1-u5-C9","difficulty":1,"kind":"mc","stem":"발표할 때 목소리를 크게 하는 까닭은 무엇인가요?","options":[{"t":"듣는 사람에게 잘 들리게 하려고","correct":true},{"t":"다른 친구를 이기려고","mis":"K4-1-u5-X09"},{"t":"발표를 빨리 끝내려고","mis":"K4-1-u5-X10"},{"t":"떨리는 마음을 감추려고","mis":"K4-1-u5-X09"}],"explanation":["누구를 위해?","듣는 사람","잘 들리게 하려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#3','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C15',1,'mc','auto','자료를 가져다 쓸 때 꼭 밝혀야 하는 것은 무엇인가요?',ARRAY['K4-1-u5-X14']::text[],false,'{"seq":3,"concept":"K4-1-u5-C15","difficulty":1,"kind":"mc","stem":"자료를 가져다 쓸 때 꼭 밝혀야 하는 것은 무엇인가요?","options":[{"t":"자료를 어디서 가져왔는지","correct":true},{"t":"자료를 찾은 사람의 키","mis":"K4-1-u5-X14"},{"t":"자료를 찾은 시각","mis":"K4-1-u5-X14"},{"t":"아무것도 밝히지 않아도 된다","mis":"K4-1-u5-X14"}],"explanation":["출처","어디서?","밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#4','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C17',1,'mc','auto','「짱뚱어를 소개합니다」의 ⑤와 마지막 줄은 발표의 어느 부분인가요?',ARRAY['K4-1-u5-X16','K4-1-u5-X14']::text[],false,'{"seq":4,"concept":"K4-1-u5-C17","difficulty":1,"kind":"mc","stem":"「짱뚱어를 소개합니다」의 ⑤와 마지막 줄은 발표의 어느 부분인가요?","options":[{"t":"끝맺는 말","correct":true},{"t":"시작하는 말","mis":"K4-1-u5-X16"},{"t":"설명하는 말","mis":"K4-1-u5-X16"},{"t":"자료의 출처","mis":"K4-1-u5-X14"}],"explanation":["정리","인사","끝맺는 말이에요."],"asset":{"type":"passage","lines":["① 안녕하세요? 지금부터 갯벌에 사는 물고기 짱뚱어를 소개하겠습니다.","② 짱뚱어는 눈이 머리 위로 툭 튀어나와 있습니다. (어린이 백과사전)","③ 가슴지느러미로 진흙 위를 기어 다니며 아주 작은 먹이를 먹습니다.","④ 갯벌이 줄어들면서 짱뚱어가 살 곳도 줄고 있습니다.","⑤ 지금까지 짱뚱어의 생김새와 먹이, 사는 곳을 알아보았습니다.","들어 주셔서 고맙습니다."],"title":"짱뚱어를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#5','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C26',1,'mc','auto','「빨간 장화 한 짝」 감상문의 ①은 무엇을 쓴 곳인가요?',ARRAY['K4-1-u5-X32']::text[],false,'{"seq":5,"concept":"K4-1-u5-C26","difficulty":1,"kind":"mc","stem":"「빨간 장화 한 짝」 감상문의 ①은 무엇을 쓴 곳인가요?","options":[{"t":"책을 읽은 까닭","correct":true},{"t":"생각이나 느낌","mis":"K4-1-u5-X32"},{"t":"인상 깊은 장면","mis":"K4-1-u5-X32"},{"t":"책의 내용","mis":"K4-1-u5-X32"}],"explanation":["왜 꺼냈나요?","궁금해서","읽은 까닭이에요."],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#6','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C33',1,'mc','auto','읽을 책을 고르는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X33']::text[],false,'{"seq":6,"concept":"K4-1-u5-C33","difficulty":1,"kind":"mc","stem":"읽을 책을 고르는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"알고 싶은 내용이 담긴 책을 고른다","correct":true},{"t":"가장 얇은 책을 고른다","mis":"K4-1-u5-X33"},{"t":"표지를 보지 않고 아무거나 집는다","mis":"K4-1-u5-X33"},{"t":"글자 수가 가장 적은 책을 고른다","mis":"K4-1-u5-X33"}],"explanation":["읽고 싶은 까닭","알고 싶은 내용","골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#7','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C35',1,'mc','auto','독서 감상문의 가운데 부분에 쓰기 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X35','K4-1-u5-X26']::text[],false,'{"seq":7,"concept":"K4-1-u5-C35","difficulty":1,"kind":"mc","stem":"독서 감상문의 가운데 부분에 쓰기 알맞은 것은 무엇인가요?","options":[{"t":"책의 내용과 인상 깊은 장면","correct":true},{"t":"책을 읽게 된 까닭","mis":"K4-1-u5-X35"},{"t":"책을 읽고 한 다짐만","mis":"K4-1-u5-X35"},{"t":"책값","mis":"K4-1-u5-X26"}],"explanation":["가운데에는","책 이야기","내용과 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#8','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C48',1,'mc','auto','「마음씨가 부드럽고 다정하다」를 뜻하는 순우리말은 무엇인가요?',ARRAY['K4-1-u5-X46']::text[],false,'{"seq":8,"concept":"K4-1-u5-C48","difficulty":1,"kind":"mc","stem":"「마음씨가 부드럽고 다정하다」를 뜻하는 순우리말은 무엇인가요?","options":[{"t":"살갑다","correct":true},{"t":"옹골지다","mis":"K4-1-u5-X46"},{"t":"도란도란","mis":"K4-1-u5-X46"},{"t":"도담도담","mis":"K4-1-u5-X46"}],"explanation":["부드럽고","다정하다","살갑다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#9','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C6',2,'mc','auto','하람이처럼 발표에 자신감이 생기려면 어떻게 해야 하나요?',ARRAY['K4-1-u5-X06','K4-1-u5-X02']::text[],false,'{"seq":9,"concept":"K4-1-u5-C6","difficulty":2,"kind":"mc","stem":"하람이처럼 발표에 자신감이 생기려면 어떻게 해야 하나요?","options":[{"t":"날마다 조금씩 알아보며 발표를 준비한다","correct":true},{"t":"원래 목소리가 커야 한다","mis":"K4-1-u5-X06"},{"t":"발표를 피한다","mis":"K4-1-u5-X02"},{"t":"친구에게 대신 맡긴다","mis":"K4-1-u5-X02"}],"explanation":["하람이가 한 일","날마다 조금씩","준비해요."],"asset":{"type":"passage","lines":["하람이는 친구들 앞에서 말하는 일이 가장 무서웠다.","발표 숙제를 받자 종이를 접어 가방 깊숙이 넣었다.","하람이는 여름밤마다 보던 북두칠성을 발표하기로 했다.","별자리 책을 찾고, 할머니께 여쭙고, 사진도 확인했다.","날마다 조금씩 알아보는 동안 긴장한 것도 잊었다.","발표 날, 한 문장을 떼자 목소리가 조금씩 커졌다."],"title":"목소리를 찾은 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#10','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C19',2,'mc','auto','발표할 때 주의할 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X18']::text[],false,'{"seq":10,"concept":"K4-1-u5-C19","difficulty":2,"kind":"mc","stem":"발표할 때 주의할 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"자료를 처음부터 끝까지 그대로 읽기만 한다","correct":true},{"t":"중요한 내용은 목소리를 조금 크게 한다","mis":"K4-1-u5-X18"},{"t":"새 자료는 손으로 가리켜 알린다","mis":"K4-1-u5-X18"},{"t":"듣는 사람과 눈을 맞춘다","mis":"K4-1-u5-X18"}],"explanation":["그대로 읽기만?","듣는 사람을 봐요.","그건 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#11','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C16',2,'mc','auto','조사한 내용을 표로 정리하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X15','K4-1-u5-X14','K4-1-u5-X12']::text[],false,'{"seq":11,"concept":"K4-1-u5-C16","difficulty":2,"kind":"mc","stem":"조사한 내용을 표로 정리하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"알고 싶은 점마다 찾은 내용과 출처를 함께 적는다","correct":true},{"t":"찾은 내용을 아무 칸에나 적는다","mis":"K4-1-u5-X15"},{"t":"출처는 적지 않는다","mis":"K4-1-u5-X14"},{"t":"알고 싶은 점과 상관없는 내용도 모두 적는다","mis":"K4-1-u5-X12"}],"explanation":["항목마다","내용과 출처","함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#12','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C28',2,'mc','auto','「빨간 장화 한 짝」 감상문에서 ④ 다음에 ⑤를 쓴 까닭은 무엇인가요?',ARRAY['K4-1-u5-X31','K4-1-u5-X32','K4-1-u5-X28']::text[],false,'{"seq":12,"concept":"K4-1-u5-C28","difficulty":2,"kind":"mc","stem":"「빨간 장화 한 짝」 감상문에서 ④ 다음에 ⑤를 쓴 까닭은 무엇인가요?","options":[{"t":"인상 깊은 장면이 왜 기억에 남았는지 밝히려고","correct":true},{"t":"책의 줄거리를 더 늘리려고","mis":"K4-1-u5-X31"},{"t":"책을 읽은 까닭을 쓰려고","mis":"K4-1-u5-X32"},{"t":"글자 수를 채우려고","mis":"K4-1-u5-X28"}],"explanation":["④는 장면","⑤는?","까닭이에요."],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#13','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C37',2,'mc','auto','잘 쓴 독서 감상문의 조건으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X31','K4-1-u5-X25','K4-1-u5-X30']::text[],false,'{"seq":13,"concept":"K4-1-u5-C37","difficulty":2,"kind":"mc","stem":"잘 쓴 독서 감상문의 조건으로 알맞은 것은 무엇인가요?","options":[{"t":"인상 깊은 장면을 까닭과 함께 썼다","correct":true},{"t":"책의 모든 장면을 빠짐없이 적었다","mis":"K4-1-u5-X31"},{"t":"책 제목을 그대로 제목으로 썼다","mis":"K4-1-u5-X25"},{"t":"생각이나 느낌은 되도록 적게 썼다","mis":"K4-1-u5-X30"}],"explanation":["장면과 까닭","자세한 느낌","조건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#14','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C43',2,'match','auto','친구가 감상문에 쓴 내용과 어울리는 댓글을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"K4-1-u5-C43","difficulty":2,"kind":"match","stem":"친구가 감상문에 쓴 내용과 어울리는 댓글을 알맞게 이으세요.","pairs":[{"l":"리아가 쪽지를 붙인 일이 멋졌다","r":"나도 주운 물건 주인을 찾아 주고 싶어졌어."},{"l":"빨간 장화 그림이 예뻤다","r":"네 글을 읽고 그 그림이 보고 싶어졌어."},{"l":"나도 우산을 주운 적이 있다","r":"네 경험을 함께 써서 더 와닿았어."}],"mis":"K4-1-u5-X42","explanation":["친구가 쓴 내용","그에 맞게","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#15','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C47',2,'mc','auto','듣는 사람도 발표에 함께 참여하는 사람이에요. 그렇게 듣는 모습으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X19','K4-1-u5-X45']::text[],false,'{"seq":15,"concept":"K4-1-u5-C47","difficulty":2,"kind":"mc","stem":"듣는 사람도 발표에 함께 참여하는 사람이에요. 그렇게 듣는 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"발표자를 바라보며 끝까지 듣고 중요한 내용을 적는다","correct":true},{"t":"발표자를 등지고 앉는다","mis":"K4-1-u5-X19"},{"t":"적는 것은 딴짓이라 손을 놓는다","mis":"K4-1-u5-X45"},{"t":"중간에 끼어들어 다른 이야기를 한다","mis":"K4-1-u5-X19"}],"explanation":["바라보며","적으며","끝까지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#16','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C5',2,'mc','auto','「발표 전에 너무 긴장해서 목소리가 떨렸다.」에서 「긴장」의 뜻은 무엇인가요?',ARRAY['K4-1-u5-X05']::text[],false,'{"seq":16,"concept":"K4-1-u5-C5","difficulty":2,"kind":"mc","stem":"「발표 전에 너무 긴장해서 목소리가 떨렸다.」에서 「긴장」의 뜻은 무엇인가요?","options":[{"t":"마음을 조이고 정신을 바짝 차림","correct":true},{"t":"마음을 놓고 편히 쉼","mis":"K4-1-u5-X05"},{"t":"알아낸 것을 여러 사람 앞에 알림","mis":"K4-1-u5-X05"},{"t":"내용을 알기 위해 자세히 살펴봄","mis":"K4-1-u5-X05"}],"explanation":["목소리가 떨렸어요.","조이는 마음","긴장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#17','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C6',3,'mc','auto','「발표는 타고난 사람만 잘할 수 있어.」라는 말을 하람이 이야기에 비추어 바르게 고친 것은 무엇인가요?',ARRAY['K4-1-u5-X06','K4-1-u5-X02','K4-1-u5-X09']::text[],false,'{"seq":17,"concept":"K4-1-u5-C6","difficulty":3,"kind":"mc","stem":"「발표는 타고난 사람만 잘할 수 있어.」라는 말을 하람이 이야기에 비추어 바르게 고친 것은 무엇인가요?","options":[{"t":"「하람이처럼 준비하고 연습하면 누구나 자신 있게 말할 수 있어.」","correct":true},{"t":"「맞아. 하람이도 원래 발표를 잘했어.」","mis":"K4-1-u5-X06"},{"t":"「발표는 피하는 게 나아.」","mis":"K4-1-u5-X02"},{"t":"「목소리만 크면 돼.」","mis":"K4-1-u5-X09"}],"explanation":["하람이는 원래?","무엇이 바뀌게 했나요?","준비와 연습이에요."],"asset":{"type":"passage","lines":["하람이는 친구들 앞에서 말하는 일이 가장 무서웠다.","발표 숙제를 받자 종이를 접어 가방 깊숙이 넣었다.","하람이는 여름밤마다 보던 북두칠성을 발표하기로 했다.","별자리 책을 찾고, 할머니께 여쭙고, 사진도 확인했다.","날마다 조금씩 알아보는 동안 긴장한 것도 잊었다.","발표 날, 한 문장을 떼자 목소리가 조금씩 커졌다."],"title":"목소리를 찾은 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#18','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C18',3,'mc','auto','자료에 나온 어려운 말을 쉬운 말로 바꾸려면 먼저 해야 할 일은 무엇인가요?',ARRAY['K4-1-u5-X17']::text[],false,'{"seq":18,"concept":"K4-1-u5-C18","difficulty":3,"kind":"mc","stem":"자료에 나온 어려운 말을 쉬운 말로 바꾸려면 먼저 해야 할 일은 무엇인가요?","options":[{"t":"내가 그 말의 뜻을 이해한다","correct":true},{"t":"어려운 말을 그대로 외운다","mis":"K4-1-u5-X17"},{"t":"어려운 말은 모두 지운다","mis":"K4-1-u5-X17"},{"t":"뜻을 몰라도 비슷한 말을 아무거나 넣는다","mis":"K4-1-u5-X17"}],"explanation":["바꾸려면","먼저 알아야","이해해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#19','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C29',3,'mc','auto','다온이의 감상문 마지막 문장 「재미있었다.」를 더 좋게 바꾼 것은 무엇인가요?',ARRAY['K4-1-u5-X29','K4-1-u5-X27']::text[],false,'{"seq":19,"concept":"K4-1-u5-C29","difficulty":3,"kind":"mc","stem":"다온이의 감상문 마지막 문장 「재미있었다.」를 더 좋게 바꾼 것은 무엇인가요?","options":[{"t":"느리지만 끝까지 짐을 나른 거북처럼 나도 맡은 일을 끝까지 해내고 싶다.","correct":true},{"t":"아주아주 재미있었다.","mis":"K4-1-u5-X29"},{"t":"거북이 마을에 도착했다.","mis":"K4-1-u5-X27"},{"t":"끝.","mis":"K4-1-u5-X29"}],"explanation":["한마디로 끝?","깨달은 점","다짐을 써요."],"asset":{"type":"passage","lines":["거북이 산 너머 마을로 가는 짐을 맡았다.","첫째 날에는 언덕을 넘었다.","둘째 날에는 비가 와서 나뭇잎 아래에서 쉬었다.","셋째 날에는 냇물을 건넜다.","넷째 날에 마을에 도착해 짐을 건넸다.","재미있었다."],"title":"다온이의 독서 감상문 — 「느림보 거북 택배」를 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#20','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C39',3,'mc','auto','「빨간 장화 한 짝」의 감상을 편지 형식으로 쓸 때 시작으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X38','K4-1-u5-X24']::text[],false,'{"seq":20,"concept":"K4-1-u5-C39","difficulty":3,"kind":"mc","stem":"「빨간 장화 한 짝」의 감상을 편지 형식으로 쓸 때 시작으로 알맞은 것은 무엇인가요?","options":[{"t":"「리아야, 네가 붙인 쪽지 이야기를 읽고 편지를 써.」","correct":true},{"t":"편지로 쓰면 책 이야기는 빼야 하니 인사만 쓴다.","mis":"K4-1-u5-X38"},{"t":"편지 형식은 감상문이 아니니 쓸 수 없다.","mis":"K4-1-u5-X38"},{"t":"책을 산 가게 이름부터 쓴다.","mis":"K4-1-u5-X24"}],"explanation":["누구에게?","책 이야기","편지로 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#21','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C43',3,'mc','auto','친구가 감상문에 「천둥을 무서워하던 동생과 함께 읽어 좋았다」라고 썼어요. 어울리는 댓글은 무엇인가요?',ARRAY['K4-1-u5-X42','K4-1-u5-X41']::text[],false,'{"seq":21,"concept":"K4-1-u5-C43","difficulty":3,"kind":"mc","stem":"친구가 감상문에 「천둥을 무서워하던 동생과 함께 읽어 좋았다」라고 썼어요. 어울리는 댓글은 무엇인가요?","options":[{"t":"「동생과 함께 읽은 이야기가 따뜻해. 동생은 어땠는지도 궁금해.」","correct":true},{"t":"「밤에만 여는 도서관이 신비로웠겠다.」","mis":"K4-1-u5-X42"},{"t":"「글씨를 좀 더 크게 써.」","mis":"K4-1-u5-X41"},{"t":"「나는 천둥이 하나도 안 무서워.」","mis":"K4-1-u5-X42"}],"explanation":["친구가 쓴 내용","동생과 함께","그에 맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#22','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C48',3,'mc','auto','순우리말에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u5-X47','K4-1-u5-X46']::text[],false,'{"seq":22,"concept":"K4-1-u5-C48","difficulty":3,"kind":"mc","stem":"순우리말에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"뜻을 알고 알맞은 자리에 쓰면 말이 더 곱고 또렷해진다","correct":true},{"t":"옛날 말이라 쓰면 틀린 말이 된다","mis":"K4-1-u5-X47"},{"t":"소리만 예쁘면 아무 자리에나 써도 된다","mis":"K4-1-u5-X46"},{"t":"순우리말은 지금 아무도 쓰지 않는다","mis":"K4-1-u5-X47"}],"explanation":["뜻을 알고","알맞은 자리","곱고 또렷하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#23','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C17',4,'essay','teacher','「짱뚱어를 소개합니다」를 시작하는 말 · 설명하는 말 · 끝맺는 말로 나누고, 각 부분이 하는 일을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u5-C17","difficulty":4,"kind":"essay","stem":"「짱뚱어를 소개합니다」를 시작하는 말 · 설명하는 말 · 끝맺는 말로 나누고, 각 부분이 하는 일을 쓰세요.","answer_guide":{"answer":"예: ①은 시작하는 말로 무엇을 발표할지 알린다. ②~④는 설명하는 말로 생김새 · 먹이 · 사는 곳을 차례대로 말한다. ⑤와 마지막 줄은 끝맺는 말로 내용을 정리하고 인사한다.","scoring_points":["세 부분을 바르게 나누었는가","부분마다 하는 일을 썼는가","차례가 알맞은가"]},"explanation":["①","②~④","⑤와 인사"],"asset":{"type":"passage","lines":["① 안녕하세요? 지금부터 갯벌에 사는 물고기 짱뚱어를 소개하겠습니다.","② 짱뚱어는 눈이 머리 위로 툭 튀어나와 있습니다. (어린이 백과사전)","③ 가슴지느러미로 진흙 위를 기어 다니며 아주 작은 먹이를 먹습니다.","④ 갯벌이 줄어들면서 짱뚱어가 살 곳도 줄고 있습니다.","⑤ 지금까지 짱뚱어의 생김새와 먹이, 사는 곳을 알아보았습니다.","들어 주셔서 고맙습니다."],"title":"짱뚱어를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#24','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C40',4,'essay','teacher','「빨간 장화 한 짝」 감상문의 글쓴이와 다른 장면을 인상 깊은 장면으로 골라 보고, 그 장면을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u5-C40","difficulty":4,"kind":"essay","stem":"「빨간 장화 한 짝」 감상문의 글쓴이와 다른 장면을 인상 깊은 장면으로 골라 보고, 그 장면을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 나는 리아가 놀이터 기둥에 쪽지를 붙이는 장면이 가장 인상 깊다. 주인이 누구인지도 모르면서 찾아 주려고 애쓰는 모습에서 작은 친절이 크다는 것을 느꼈기 때문이다.","scoring_points":["글쓴이와 다른 장면을 골랐는가","장면을 고른 까닭을 썼는가","까닭이 이야기 내용에 근거하는가"]},"explanation":["④가 아닌 장면","왜?","근거를 들어요."],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_b#25','kor',4,1,'u5','','g4_1_kor_u5_review_b','unit_review','K4-1-u5-C45',4,'essay','teacher','「내가 존경하는 사람」을 뽑아 1분 동안 말한다면 어떤 내용을 어떤 차례로 말할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u5-C45","difficulty":4,"kind":"essay","stem":"「내가 존경하는 사람」을 뽑아 1분 동안 말한다면 어떤 내용을 어떤 차례로 말할지 쓰세요.","answer_guide":{"answer":"예: 먼저 존경하는 사람이 우리 할머니라고 밝힌다. 다음으로 할머니가 날마다 동네 길을 쓸어 오신 일을 말한다. 끝으로 그 모습을 보며 나도 남을 위해 일하고 싶어졌다고 말한다.","scoring_points":["주제에 맞는 내용을 골랐는가","차례를 정해 썼는가","까닭이나 느낌을 담았는가"]},"explanation":["누구?","무엇을 했나요?","내 생각"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#1','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C1',1,'mc','auto','이 단원에서 글로 생각을 전하는 방법으로 배운 것은 무엇인가요?',ARRAY['K4-1-u5-X01']::text[],false,'{"seq":1,"concept":"K4-1-u5-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 글로 생각을 전하는 방법으로 배운 것은 무엇인가요?","options":[{"t":"독서 감상문 쓰기","correct":true},{"t":"어림하여 계산하기","mis":"K4-1-u5-X01"},{"t":"인형극 하기","mis":"K4-1-u5-X01"},{"t":"친구 이름 외우기","mis":"K4-1-u5-X01"}],"explanation":["글로 전하기","책을 읽고","감상문 쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#2','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C2',1,'mc','auto','발표가 떨릴 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K4-1-u5-X02','K4-1-u5-X06']::text[],false,'{"seq":2,"concept":"K4-1-u5-C2","difficulty":1,"kind":"mc","stem":"발표가 떨릴 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"발표할 내용을 미리 찾아 정리하고 연습한다","correct":true},{"t":"발표 날까지 아예 생각하지 않는다","mis":"K4-1-u5-X02"},{"t":"다른 친구에게 발표를 넘긴다","mis":"K4-1-u5-X02"},{"t":"목소리만 크면 된다고 여긴다","mis":"K4-1-u5-X06"}],"explanation":["준비","연습","자신감이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#3','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C13',1,'mc','auto','발표 자료를 얻는 곳으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X13']::text[],false,'{"seq":3,"concept":"K4-1-u5-C13","difficulty":1,"kind":"mc","stem":"발표 자료를 얻는 곳으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"내가 짐작해서 지어낸 이야기","correct":true},{"t":"백과사전","mis":"K4-1-u5-X13"},{"t":"믿을 만한 누리집","mis":"K4-1-u5-X13"},{"t":"그 내용을 잘 아는 사람","mis":"K4-1-u5-X13"}],"explanation":["어디에서 찾을까요?","짐작은?","지어내면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#4','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C17',1,'mc','auto','「짱뚱어를 소개합니다」의 ②~④는 발표의 어느 부분인가요?',ARRAY['K4-1-u5-X16']::text[],false,'{"seq":4,"concept":"K4-1-u5-C17","difficulty":1,"kind":"mc","stem":"「짱뚱어를 소개합니다」의 ②~④는 발표의 어느 부분인가요?","options":[{"t":"설명하는 말","correct":true},{"t":"시작하는 말","mis":"K4-1-u5-X16"},{"t":"끝맺는 말","mis":"K4-1-u5-X16"},{"t":"듣는 사람의 칭찬","mis":"K4-1-u5-X16"}],"explanation":["조사한 내용","차례대로","설명하는 말이에요."],"asset":{"type":"passage","lines":["① 안녕하세요? 지금부터 갯벌에 사는 물고기 짱뚱어를 소개하겠습니다.","② 짱뚱어는 눈이 머리 위로 툭 튀어나와 있습니다. (어린이 백과사전)","③ 가슴지느러미로 진흙 위를 기어 다니며 아주 작은 먹이를 먹습니다.","④ 갯벌이 줄어들면서 짱뚱어가 살 곳도 줄고 있습니다.","⑤ 지금까지 짱뚱어의 생김새와 먹이, 사는 곳을 알아보았습니다.","들어 주셔서 고맙습니다."],"title":"짱뚱어를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#5','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C27',1,'mc','auto','「빨간 장화 한 짝」 감상문의 ②와 ③은 무엇을 쓴 곳인가요?',ARRAY['K4-1-u5-X32']::text[],false,'{"seq":5,"concept":"K4-1-u5-C27","difficulty":1,"kind":"mc","stem":"「빨간 장화 한 짝」 감상문의 ②와 ③은 무엇을 쓴 곳인가요?","options":[{"t":"책의 내용","correct":true},{"t":"생각이나 느낌","mis":"K4-1-u5-X32"},{"t":"책을 읽은 까닭","mis":"K4-1-u5-X32"},{"t":"제목","mis":"K4-1-u5-X32"}],"explanation":["리아가 한 일","책 속 이야기","책의 내용이에요."],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#6','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C33',1,'mc','auto','재미있게 읽은 책이 있을 때 다음 책을 고르는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X33']::text[],false,'{"seq":6,"concept":"K4-1-u5-C33","difficulty":1,"kind":"mc","stem":"재미있게 읽은 책이 있을 때 다음 책을 고르는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"그 책의 지은이가 쓴 다른 책을 찾아본다","correct":true},{"t":"가장 빨리 읽을 수 있는 책을 고른다","mis":"K4-1-u5-X33"},{"t":"제목이 가장 짧은 책을 고른다","mis":"K4-1-u5-X33"},{"t":"읽어 본 적 없는 분야는 아예 고르지 않는다","mis":"K4-1-u5-X33"}],"explanation":["재미있었던 책","같은 지은이","찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#7','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C39',1,'mc','auto','독서 감상문의 형식으로 볼 수 없는 것은 무엇인가요?',ARRAY['K4-1-u5-X38']::text[],false,'{"seq":7,"concept":"K4-1-u5-C39","difficulty":1,"kind":"mc","stem":"독서 감상문의 형식으로 볼 수 없는 것은 무엇인가요?","options":[{"t":"책 제목만 열 번 따라 쓰기","correct":true},{"t":"등장인물에게 쓰는 편지","mis":"K4-1-u5-X38"},{"t":"인물이 되어 쓰는 일기","mis":"K4-1-u5-X38"},{"t":"친구와 묻고 답하는 인터뷰","mis":"K4-1-u5-X38"}],"explanation":["편지 · 일기 · 인터뷰","감상이 담겼나요?","따라 쓰기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#8','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C48',1,'mc','auto','「실속 있게 속이 꽉 차 있다」를 뜻하는 순우리말은 무엇인가요?',ARRAY['K4-1-u5-X46']::text[],false,'{"seq":8,"concept":"K4-1-u5-C48","difficulty":1,"kind":"mc","stem":"「실속 있게 속이 꽉 차 있다」를 뜻하는 순우리말은 무엇인가요?","options":[{"t":"옹골지다","correct":true},{"t":"살갑다","mis":"K4-1-u5-X46"},{"t":"도란도란","mis":"K4-1-u5-X46"},{"t":"도담도담","mis":"K4-1-u5-X46"}],"explanation":["속이 꽉","실속 있게","옹골지다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#9','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C7',2,'mc','auto','하람이에게 묻는 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X07']::text[],false,'{"seq":9,"concept":"K4-1-u5-C7","difficulty":2,"kind":"mc","stem":"하람이에게 묻는 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"「발표 날 칠판 앞에서 눈을 감은 까닭은 무엇인가요?」","correct":true},{"t":"「신발 크기는 몇인가요?」","mis":"K4-1-u5-X07"},{"t":"「가방은 몇 개 있나요?」","mis":"K4-1-u5-X07"},{"t":"「좋아하는 과일은 무엇인가요?」","mis":"K4-1-u5-X07"}],"explanation":["이야기 속 일","그때의 마음","까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#10','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C20',2,'mc','auto','짱뚱어 발표를 듣고 구체적으로 칭찬한 말은 무엇인가요?',ARRAY['K4-1-u5-X20']::text[],false,'{"seq":10,"concept":"K4-1-u5-C20","difficulty":2,"kind":"mc","stem":"짱뚱어 발표를 듣고 구체적으로 칭찬한 말은 무엇인가요?","options":[{"t":"「사진을 가리키며 눈 모양을 설명해서 쉽게 알았어.」","correct":true},{"t":"「잘했어.」","mis":"K4-1-u5-X20"},{"t":"「나라면 더 잘했을 거야.」","mis":"K4-1-u5-X20"},{"t":"「목소리가 작아서 별로였어.」","mis":"K4-1-u5-X20"}],"explanation":["무엇을 잘했나요?","짚어서","구체적으로 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#11','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C15',2,'mc','auto','「짱뚱어를 소개합니다」 ②에 「(어린이 백과사전)」을 적은 까닭은 무엇인가요?',ARRAY['K4-1-u5-X14']::text[],false,'{"seq":11,"concept":"K4-1-u5-C15","difficulty":2,"kind":"mc","stem":"「짱뚱어를 소개합니다」 ②에 「(어린이 백과사전)」을 적은 까닭은 무엇인가요?","options":[{"t":"그 내용을 어디서 가져왔는지 밝히려고","correct":true},{"t":"발표를 길어 보이게 하려고","mis":"K4-1-u5-X14"},{"t":"백과사전을 사라고 알리려고","mis":"K4-1-u5-X14"},{"t":"내가 쓴 책이라서","mis":"K4-1-u5-X14"}],"explanation":["괄호 속","어디서?","출처예요."],"asset":{"type":"passage","lines":["① 안녕하세요? 지금부터 갯벌에 사는 물고기 짱뚱어를 소개하겠습니다.","② 짱뚱어는 눈이 머리 위로 툭 튀어나와 있습니다. (어린이 백과사전)","③ 가슴지느러미로 진흙 위를 기어 다니며 아주 작은 먹이를 먹습니다.","④ 갯벌이 줄어들면서 짱뚱어가 살 곳도 줄고 있습니다.","⑤ 지금까지 짱뚱어의 생김새와 먹이, 사는 곳을 알아보았습니다.","들어 주셔서 고맙습니다."],"title":"짱뚱어를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#12','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C30',2,'mc','auto','독서 감상문에 줄거리만 쓰면 생기는 문제는 무엇인가요?',ARRAY['K4-1-u5-X30','K4-1-u5-X25','K4-1-u5-X31']::text[],false,'{"seq":12,"concept":"K4-1-u5-C30","difficulty":2,"kind":"mc","stem":"독서 감상문에 줄거리만 쓰면 생기는 문제는 무엇인가요?","options":[{"t":"글쓴이의 생각이나 느낌이 빠진다","correct":true},{"t":"무슨 책인지 알 수 없다","mis":"K4-1-u5-X30"},{"t":"제목을 붙일 수 없다","mis":"K4-1-u5-X25"},{"t":"글이 너무 짧아진다","mis":"K4-1-u5-X31"}],"explanation":["줄거리만 있으면","내 마음은?","빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#13','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C34',2,'mc','auto','「빨간 장화 한 짝」 감상문을 쓰기 전에 「인상 깊은 장면」 칸에 정리할 내용은 무엇인가요?',ARRAY['K4-1-u5-X34']::text[],false,'{"seq":13,"concept":"K4-1-u5-C34","difficulty":2,"kind":"mc","stem":"「빨간 장화 한 짝」 감상문을 쓰기 전에 「인상 깊은 장면」 칸에 정리할 내용은 무엇인가요?","options":[{"t":"쪽지 아래에 고맙다는 글씨가 적혀 있던 장면","correct":true},{"t":"빨간 장화 그림이 궁금했다","mis":"K4-1-u5-X34"},{"t":"주운 물건의 주인을 찾아 주려고 애써야겠다","mis":"K4-1-u5-X34"},{"t":"학급 문고에서 꺼냈다","mis":"K4-1-u5-X34"}],"explanation":["기억에 남은 장면","④를 봐요.","칸에 맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#14','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C45',2,'mc','auto','「우리 가족」을 뽑아 1분 동안 말할 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X44','K4-1-u5-X02']::text[],false,'{"seq":14,"concept":"K4-1-u5-C45","difficulty":2,"kind":"mc","stem":"「우리 가족」을 뽑아 1분 동안 말할 때 알맞은 것은 무엇인가요?","options":[{"t":"가족을 한 사람씩 차례대로 소개한다","correct":true},{"t":"어제 본 만화 이야기를 한다","mis":"K4-1-u5-X44"},{"t":"같은 문장을 1분 동안 되풀이한다","mis":"K4-1-u5-X44"},{"t":"어려우니 말하지 않는다","mis":"K4-1-u5-X02"}],"explanation":["뽑은 주제","차례대로","주제에 맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#15','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C49',2,'mc','auto','모음 「ㅗ」 위에 「ㅅ」이 놓인 글자는 무엇인가요?',ARRAY['K4-1-u5-X48']::text[],false,'{"seq":15,"concept":"K4-1-u5-C49","difficulty":2,"kind":"mc","stem":"모음 「ㅗ」 위에 「ㅅ」이 놓인 글자는 무엇인가요?","options":[{"t":"소","correct":true},{"t":"사","mis":"K4-1-u5-X48"},{"t":"앗","mis":"K4-1-u5-X48"},{"t":"시","mis":"K4-1-u5-X48"}],"explanation":["ㅗ는 아래에","ㅅ은 위에","소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#16','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C32',2,'mc','auto','「나도 하고 싶은 말을 마음속에만 담아 둔 적이 있어서 뜨끔했다.」는 감상문에서 무엇에 해당하나요?',ARRAY['K4-1-u5-X32']::text[],false,'{"seq":16,"concept":"K4-1-u5-C32","difficulty":2,"kind":"mc","stem":"「나도 하고 싶은 말을 마음속에만 담아 둔 적이 있어서 뜨끔했다.」는 감상문에서 무엇에 해당하나요?","options":[{"t":"책을 읽고 떠오른 생각이나 느낌","correct":true},{"t":"책의 내용","mis":"K4-1-u5-X32"},{"t":"책을 읽은 까닭","mis":"K4-1-u5-X32"},{"t":"제목","mis":"K4-1-u5-X32"}],"explanation":["나도","뜨끔했다","내 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#17','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C11',3,'mc','auto','「종이만 보며 읽었다」는 아쉬운 점을 고치는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X11']::text[],false,'{"seq":17,"concept":"K4-1-u5-C11","difficulty":3,"kind":"mc","stem":"「종이만 보며 읽었다」는 아쉬운 점을 고치는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"듣는 사람을 바라보며 말한다","correct":true},{"t":"더 크게 소리친다","mis":"K4-1-u5-X11"},{"t":"더 빨리 읽는다","mis":"K4-1-u5-X11"},{"t":"종이를 새것으로 바꾼다","mis":"K4-1-u5-X11"}],"explanation":["종이만 보았어요.","누구를 봐야 하나요?","듣는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#18','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C17',3,'mc','auto','수목원을 소개하는 발표의 시작하는 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X16']::text[],false,'{"seq":18,"concept":"K4-1-u5-C17","difficulty":3,"kind":"mc","stem":"수목원을 소개하는 발표의 시작하는 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「안녕하세요? 지금부터 우리 고장 수목원을 소개하겠습니다.」","correct":true},{"t":"「들어 주셔서 고맙습니다.」","mis":"K4-1-u5-X16"},{"t":"「소나무 숲길이 볼거리입니다.」","mis":"K4-1-u5-X16"},{"t":"「지금까지 수목원을 알아보았습니다.」","mis":"K4-1-u5-X16"}],"explanation":["처음","무엇을 소개할지","시작하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#19','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C22',3,'mc','auto','친구가 「줄거리만 정리하면 감상문은 끝이야.」라고 했어요. 가장 알맞게 대답한 것은 무엇인가요?',ARRAY['K4-1-u5-X22','K4-1-u5-X30','K4-1-u5-X24']::text[],false,'{"seq":19,"concept":"K4-1-u5-C22","difficulty":3,"kind":"mc","stem":"친구가 「줄거리만 정리하면 감상문은 끝이야.」라고 했어요. 가장 알맞게 대답한 것은 무엇인가요?","options":[{"t":"「감상문은 책을 읽고 생각이나 느낌을 쓴 글이라 내 마음이 들어가야 해.」","correct":true},{"t":"「맞아. 줄거리가 전부야.」","mis":"K4-1-u5-X22"},{"t":"「줄거리는 아예 빼야 해.」","mis":"K4-1-u5-X30"},{"t":"「쪽수만 적으면 돼.」","mis":"K4-1-u5-X24"}],"explanation":["감상문은?","내 마음","함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#20','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C40',3,'mc','auto','「빨간 장화 한 짝」을 읽고 은솔이는 쪽지 아래 글씨를 발견한 장면을, 시우는 쪽지를 붙이는 장면을 골랐어요. 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u5-X39','K4-1-u5-X28']::text[],false,'{"seq":20,"concept":"K4-1-u5-C40","difficulty":3,"kind":"mc","stem":"「빨간 장화 한 짝」을 읽고 은솔이는 쪽지 아래 글씨를 발견한 장면을, 시우는 쪽지를 붙이는 장면을 골랐어요. 바르게 말한 것은 무엇인가요?","options":[{"t":"두 사람 모두 까닭을 들어 말한다면 둘 다 알맞다","correct":true},{"t":"뒤쪽 장면을 고른 은솔이만 맞다","mis":"K4-1-u5-X39"},{"t":"둘 중 한 사람은 틀렸다","mis":"K4-1-u5-X39"},{"t":"까닭이 없어도 아무 장면이나 괜찮다","mis":"K4-1-u5-X28"}],"explanation":["저마다 달라요.","까닭이 있나요?","둘 다 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#21','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C41',3,'mc','auto','시우가 소개 원고에 다람쥐 이야기를 넣은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X40','K4-1-u5-X16']::text[],false,'{"seq":21,"concept":"K4-1-u5-C41","difficulty":3,"kind":"mc","stem":"시우가 소개 원고에 다람쥐 이야기를 넣은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"그곳에서 인상 깊었던 일을 들려주어 가 보고 싶게 하려고","correct":true},{"t":"발표를 길게 하려고","mis":"K4-1-u5-X40"},{"t":"다람쥐의 이름을 알리려고","mis":"K4-1-u5-X40"},{"t":"끝맺는 말이라서","mis":"K4-1-u5-X16"}],"explanation":["④를 봐요.","인상 깊었던 일","가 보고 싶게"],"asset":{"type":"passage","lines":["① 지금부터 제가 다녀온 솔바람 수목원을 소개하겠습니다.","② 솔바람 수목원은 우리 고장 북쪽 산자락에 있습니다.","③ 키 큰 소나무 숲길과 작은 연못이 볼거리입니다.","④ 연못가에서 다람쥐가 도토리를 물고 달려가는 모습을 보았습니다."],"title":"시우의 소개 원고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#22','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C49',3,'mc','auto','「쓸다」, 「씨앗」처럼 ㅆ을 쓸 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X48']::text[],false,'{"seq":22,"concept":"K4-1-u5-C49","difficulty":3,"kind":"mc","stem":"「쓸다」, 「씨앗」처럼 ㅆ을 쓸 때 알맞은 것은 무엇인가요?","options":[{"t":"두 ㅅ을 붙여 한 글자 칸 안에 어울리게 쓴다","correct":true},{"t":"두 ㅅ을 서로 멀리 떨어뜨려 쓴다","mis":"K4-1-u5-X48"},{"t":"ㅆ을 칸 밖으로 삐져나오게 크게 쓴다","mis":"K4-1-u5-X48"},{"t":"어느 자리에서나 ㅅ 하나와 같은 크기로 쓴다","mis":"K4-1-u5-X48"}],"explanation":["두 ㅅ","한 칸 안에","어울리게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#23','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C20',4,'essay','teacher','친구의 발표를 들을 때 할 일을 두 가지 쓰고, 듣는 사람도 그렇게 해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u5-C20","difficulty":4,"kind":"essay","stem":"친구의 발표를 들을 때 할 일을 두 가지 쓰고, 듣는 사람도 그렇게 해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 발표하는 친구를 바라보며 끝까지 듣는다. 잘한 점을 찾아 구체적으로 칭찬한다. 듣는 사람도 발표에 함께 참여하는 사람이고, 잘 들어 주면 발표하는 친구가 더 자신 있게 말할 수 있기 때문이다.","scoring_points":["듣는 태도 두 가지를 썼는가","칭찬을 구체적으로 한다고 썼는가","까닭을 썼는가"]},"explanation":["바라보며","칭찬","함께 참여해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#24','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C29',4,'essay','teacher','다온이의 감상문에 이어 쓸 인상 깊은 장면과 까닭, 생각이나 느낌을 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u5-C29","difficulty":4,"kind":"essay","stem":"다온이의 감상문에 이어 쓸 인상 깊은 장면과 까닭, 생각이나 느낌을 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 거북이 비가 와도 짐이 젖지 않게 나뭇잎 아래에서 지키는 장면이 가장 기억에 남았다. 느려도 맡은 일을 소중히 여기는 마음이 느껴졌기 때문이다. 나도 맡은 당번 일을 끝까지 책임지겠다.","scoring_points":["인상 깊은 장면을 썼는가","까닭을 썼는가","생각이나 느낌을 「재미있었다」보다 자세히 썼는가"]},"explanation":["어떤 장면?","왜?","내 다짐"],"asset":{"type":"passage","lines":["거북이 산 너머 마을로 가는 짐을 맡았다.","첫째 날에는 언덕을 넘었다.","둘째 날에는 비가 와서 나뭇잎 아래에서 쉬었다.","셋째 날에는 냇물을 건넜다.","넷째 날에 마을에 도착해 짐을 건넸다.","재미있었다."],"title":"다온이의 독서 감상문 — 「느림보 거북 택배」를 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_c#25','kor',4,1,'u5','','g4_1_kor_u5_review_c','unit_review','K4-1-u5-C48',4,'essay','teacher','순우리말 「도란도란」과 「살갑다」를 넣어 각각 문장을 쓰고, 두 낱말의 뜻을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u5-C48","difficulty":4,"kind":"essay","stem":"순우리말 「도란도란」과 「살갑다」를 넣어 각각 문장을 쓰고, 두 낱말의 뜻을 쓰세요.","answer_guide":{"answer":"예: 저녁을 먹고 가족이 도란도란 이야기를 나누었다. 이웃 할머니는 늘 살갑게 인사해 주신다. 도란도란은 여럿이 나직한 목소리로 정답게 이야기하는 모양이고, 살갑다는 마음씨가 부드럽고 다정하다는 뜻이다.","scoring_points":["「도란도란」을 뜻에 맞게 썼는가","「살갑다」를 뜻에 맞게 썼는가","두 낱말의 뜻을 썼는가"]},"explanation":["정답게 이야기","다정하게","뜻에 맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#1','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C5',1,'mc','auto','「알아낸 것을 여러 사람 앞에 알림」을 뜻하는 낱말은 무엇인가요?',ARRAY['K4-1-u5-X05']::text[],false,'{"seq":1,"concept":"K4-1-u5-C5","difficulty":1,"kind":"mc","stem":"「알아낸 것을 여러 사람 앞에 알림」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"발표","correct":true},{"t":"조사","mis":"K4-1-u5-X05"},{"t":"긴장","mis":"K4-1-u5-X05"},{"t":"감상","mis":"K4-1-u5-X05"}],"explanation":["여러 사람 앞에서","알림","발표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#2','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C11',1,'mc','auto','뒷자리 친구가 내 발표를 잘 못 들었다면 어떻게 고치면 좋을까요?',ARRAY['K4-1-u5-X11']::text[],false,'{"seq":2,"concept":"K4-1-u5-C11","difficulty":1,"kind":"mc","stem":"뒷자리 친구가 내 발표를 잘 못 들었다면 어떻게 고치면 좋을까요?","options":[{"t":"잘 들릴 만한 목소리 크기로 말한다","correct":true},{"t":"더 빨리 말한다","mis":"K4-1-u5-X11"},{"t":"종이를 얼굴 가까이 들고 읽는다","mis":"K4-1-u5-X11"},{"t":"뒷자리 친구에게 앞으로 오라고만 한다","mis":"K4-1-u5-X11"}],"explanation":["못 들었어요.","크기","잘 들리게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#3','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C12',1,'mc','auto','「갯벌에 사는 짱뚱어」를 발표할 때 조사 항목으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u5-X12']::text[],false,'{"seq":3,"concept":"K4-1-u5-C12","difficulty":1,"kind":"mc","stem":"「갯벌에 사는 짱뚱어」를 발표할 때 조사 항목으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"짱뚱어라는 이름이 몇 글자인지","correct":true},{"t":"어떻게 생겼는지","mis":"K4-1-u5-X12"},{"t":"무엇을 먹는지","mis":"K4-1-u5-X12"},{"t":"어디에 사는지","mis":"K4-1-u5-X12"}],"explanation":["짱뚱어를 소개하려면","필요한 것","글자 수는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#4','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C17',1,'mc','auto','발표에서 조사한 내용을 항목별로 차례대로 말하는 부분은 무엇인가요?',ARRAY['K4-1-u5-X16']::text[],false,'{"seq":4,"concept":"K4-1-u5-C17","difficulty":1,"kind":"mc","stem":"발표에서 조사한 내용을 항목별로 차례대로 말하는 부분은 무엇인가요?","options":[{"t":"설명하는 말","correct":true},{"t":"시작하는 말","mis":"K4-1-u5-X16"},{"t":"끝맺는 말","mis":"K4-1-u5-X16"},{"t":"인사말","mis":"K4-1-u5-X16"}],"explanation":["가운데","조사한 내용","설명하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#5','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C29',1,'mc','auto','「빨간 장화 한 짝」 감상문의 ⑥은 무엇을 쓴 곳인가요?',ARRAY['K4-1-u5-X32']::text[],false,'{"seq":5,"concept":"K4-1-u5-C29","difficulty":1,"kind":"mc","stem":"「빨간 장화 한 짝」 감상문의 ⑥은 무엇을 쓴 곳인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"책의 내용","mis":"K4-1-u5-X32"},{"t":"책을 읽은 까닭","mis":"K4-1-u5-X32"},{"t":"인상 깊은 장면","mis":"K4-1-u5-X32"}],"explanation":["나도 ~해야겠다","다짐","생각이나 느낌이에요."],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#6','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C23',1,'mc','auto','독서 감상문을 쓰면 좋은 점이 아닌 것은 무엇인가요?',ARRAY['K4-1-u5-X23']::text[],false,'{"seq":6,"concept":"K4-1-u5-C23","difficulty":1,"kind":"mc","stem":"독서 감상문을 쓰면 좋은 점이 아닌 것은 무엇인가요?","options":[{"t":"책을 더 빨리 읽게 된다","correct":true},{"t":"감동을 오래 기억한다","mis":"K4-1-u5-X23"},{"t":"친구와 느낌을 나눈다","mis":"K4-1-u5-X23"},{"t":"읽은 책을 다른 사람에게 소개한다","mis":"K4-1-u5-X23"}],"explanation":["기억 · 나눔 · 소개","빨리?","빨리 읽기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#7','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C36',1,'mc','auto','독서 감상문에서 문단은 언제 나누나요?',ARRAY['K4-1-u5-X36']::text[],false,'{"seq":7,"concept":"K4-1-u5-C36","difficulty":1,"kind":"mc","stem":"독서 감상문에서 문단은 언제 나누나요?","options":[{"t":"내용이 바뀔 때","correct":true},{"t":"두 줄마다","mis":"K4-1-u5-X36"},{"t":"쉼표마다","mis":"K4-1-u5-X36"},{"t":"나누지 않는다","mis":"K4-1-u5-X36"}],"explanation":["무엇이 바뀌나요?","내용","그때 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#8','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C42',1,'mc','auto','친구의 독서 감상문에 다는 댓글로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X41','K4-1-u5-X42']::text[],false,'{"seq":8,"concept":"K4-1-u5-C42","difficulty":1,"kind":"mc","stem":"친구의 독서 감상문에 다는 댓글로 알맞은 것은 무엇인가요?","options":[{"t":"「인물에게 쓴 편지 형식이라 마음이 잘 느껴졌어.」","correct":true},{"t":"「재미없어.」","mis":"K4-1-u5-X41"},{"t":"「글이 너무 길어. 다시 써.」","mis":"K4-1-u5-X41"},{"t":"「나는 이 책 몰라.」","mis":"K4-1-u5-X42"}],"explanation":["칭찬","구체적으로","배려해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#9','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C4',2,'mc','auto','「달빛 도서관」을 한 문장으로 가장 알맞게 소개한 것은 무엇인가요?',ARRAY['K4-1-u5-X04','K4-1-u5-X26']::text[],false,'{"seq":9,"concept":"K4-1-u5-C4","difficulty":2,"kind":"mc","stem":"「달빛 도서관」을 한 문장으로 가장 알맞게 소개한 것은 무엇인가요?","options":[{"t":"「달빛 도서관」은 읽은 책을 누군가에게 들려주고 싶어지는 책이다.","correct":true},{"t":"「달빛 도서관」은 표지가 파란 책이다.","mis":"K4-1-u5-X04"},{"t":"「달빛 도서관」은 지난주에 빌린 책이다.","mis":"K4-1-u5-X26"},{"t":"「달빛 도서관」은 모두 아흔 쪽인 책이다.","mis":"K4-1-u5-X04"}],"explanation":["책이 준 느낌","한 문장","생각을 담아요."],"asset":{"type":"passage","lines":["연우는 밤마다 잠이 오지 않아 골목을 걷곤 했다.","어느 밤, 불이 켜진 작은 도서관을 발견했다.","사서는 다 읽으면 한 사람에게 이야기해 주라고 부탁했다.","연우는 짝꿍에게 이야기를 들려주다가 처음으로 오래 대화했다."],"title":"달빛 도서관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#10','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C21',2,'mc','auto','내 발표를 점검할 때 살필 것이 아닌 것은 무엇인가요?',ARRAY['K4-1-u5-X21']::text[],false,'{"seq":10,"concept":"K4-1-u5-C21","difficulty":2,"kind":"mc","stem":"내 발표를 점검할 때 살필 것이 아닌 것은 무엇인가요?","options":[{"t":"원고의 글자 수가 반에서 가장 많았는가","correct":true},{"t":"주제와 관련된 내용인가","mis":"K4-1-u5-X21"},{"t":"출처를 밝혔는가","mis":"K4-1-u5-X21"},{"t":"쉬운 말로 말했는가","mis":"K4-1-u5-X21"}],"explanation":["주제 · 출처 · 쉬운 말","글자 수?","그건 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#11','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C13',2,'mc','auto','같은 내용을 두고 두 자료의 설명이 서로 다를 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X13']::text[],false,'{"seq":11,"concept":"K4-1-u5-C13","difficulty":2,"kind":"mc","stem":"같은 내용을 두고 두 자료의 설명이 서로 다를 때 알맞은 것은 무엇인가요?","options":[{"t":"누가 만들었는지 살펴 믿을 만한 곳의 설명을 고른다","correct":true},{"t":"더 재미있는 쪽을 고른다","mis":"K4-1-u5-X13"},{"t":"먼저 본 쪽을 고른다","mis":"K4-1-u5-X13"},{"t":"둘 다 버리고 짐작해서 쓴다","mis":"K4-1-u5-X13"}],"explanation":["누가 만들었나요?","믿을 만한 곳","살펴서 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#12','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C30',2,'mc','auto','독서 감상문에 느낌만 쓰고 책의 내용을 전혀 쓰지 않으면 생기는 문제는 무엇인가요?',ARRAY['K4-1-u5-X30','K4-1-u5-X25']::text[],false,'{"seq":12,"concept":"K4-1-u5-C30","difficulty":2,"kind":"mc","stem":"독서 감상문에 느낌만 쓰고 책의 내용을 전혀 쓰지 않으면 생기는 문제는 무엇인가요?","options":[{"t":"읽는 사람이 무슨 이야기인지 알 수 없다","correct":true},{"t":"생각이 너무 많이 드러난다","mis":"K4-1-u5-X30"},{"t":"제목이 필요 없어진다","mis":"K4-1-u5-X25"},{"t":"더 좋은 감상문이 된다","mis":"K4-1-u5-X30"}],"explanation":["느낌만 있으면","무슨 이야기?","알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#13','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C40',2,'mc','auto','같은 책을 읽고 친구는 나와 다른 장면을 골랐어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u5-X39']::text[],false,'{"seq":13,"concept":"K4-1-u5-C40","difficulty":2,"kind":"mc","stem":"같은 책을 읽고 친구는 나와 다른 장면을 골랐어요. 알맞은 생각은 무엇인가요?","options":[{"t":"마음에 남는 자리는 저마다 다를 수 있으니 친구의 까닭을 들어 본다","correct":true},{"t":"친구가 책을 잘못 읽었다","mis":"K4-1-u5-X39"},{"t":"나도 친구 장면으로 바꾸어야 한다","mis":"K4-1-u5-X39"},{"t":"둘 중 하나는 틀렸다","mis":"K4-1-u5-X39"}],"explanation":["저마다 달라요.","까닭","들어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#14','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C44',2,'mc','auto','배운 것을 생활에서 실천하는 모습으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X43','K4-1-u5-X49','K4-1-u5-X19']::text[],false,'{"seq":14,"concept":"K4-1-u5-C44","difficulty":2,"kind":"mc","stem":"배운 것을 생활에서 실천하는 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"학급 누리집에 감상문을 올리고 친구 글에 댓글을 단다","correct":true},{"t":"발표는 잘하는 친구에게만 맡긴다","mis":"K4-1-u5-X43"},{"t":"감상문은 혼자만 보고 숨긴다","mis":"K4-1-u5-X49"},{"t":"친구 발표는 듣지 않는다","mis":"K4-1-u5-X19"}],"explanation":["말로","글로","모두 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#15','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C48',2,'mc','auto','「옹골지다」에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u5-X47','K4-1-u5-X46']::text[],false,'{"seq":15,"concept":"K4-1-u5-C48","difficulty":2,"kind":"mc","stem":"「옹골지다」에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"실속 있게 속이 꽉 찬 것을 나타내는, 지금도 쓰는 순우리말이다","correct":true},{"t":"옛날에만 쓰던 말이라 지금은 쓰지 않는다","mis":"K4-1-u5-X47"},{"t":"텅 빈 것을 나타내는 말이다","mis":"K4-1-u5-X46"},{"t":"외국에서 들어온 말이다","mis":"K4-1-u5-X47"}],"explanation":["뜻은?","지금도 써요.","순우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#16','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C27',2,'mc','auto','감상문의 「책의 내용」 부분을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-1-u5-X27','K4-1-u5-X31','K4-1-u5-X26']::text[],false,'{"seq":16,"concept":"K4-1-u5-C27","difficulty":2,"kind":"mc","stem":"감상문의 「책의 내용」 부분을 바르게 쓴 것은 무엇인가요?","options":[{"t":"리아는 놀이터에서 주운 장화의 주인을 찾으려고 쪽지를 붙인다.","correct":true},{"t":"이 책을 읽고 나도 착한 사람이 되어야겠다.","mis":"K4-1-u5-X27"},{"t":"리아가 나오는 모든 문장을 그대로 옮겨 쓴다.","mis":"K4-1-u5-X31"},{"t":"이 책은 학급 문고에 있다.","mis":"K4-1-u5-X26"}],"explanation":["책 속 일","간추려","책의 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#17','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C8',3,'mc','auto','도윤이가 「짱뚱어를 소개합니다」 원고로 자신 있게 발표하려면 어떻게 해야 하나요?',ARRAY['K4-1-u5-X10','K4-1-u5-X09','K4-1-u5-X08']::text[],false,'{"seq":17,"concept":"K4-1-u5-C8","difficulty":3,"kind":"mc","stem":"도윤이가 「짱뚱어를 소개합니다」 원고로 자신 있게 발표하려면 어떻게 해야 하나요?","options":[{"t":"내용을 미리 익혀 듣는 사람을 바라보며 알맞은 빠르기로 말한다","correct":true},{"t":"원고를 더 빨리 읽는다","mis":"K4-1-u5-X10"},{"t":"가장 큰 소리로 소리친다","mis":"K4-1-u5-X09"},{"t":"원고를 더 길게 늘인다","mis":"K4-1-u5-X08"}],"explanation":["미리 익히기","바라보기","알맞은 빠르기"],"asset":{"type":"passage","lines":["① 안녕하세요? 지금부터 갯벌에 사는 물고기 짱뚱어를 소개하겠습니다.","② 짱뚱어는 눈이 머리 위로 툭 튀어나와 있습니다. (어린이 백과사전)","③ 가슴지느러미로 진흙 위를 기어 다니며 아주 작은 먹이를 먹습니다.","④ 갯벌이 줄어들면서 짱뚱어가 살 곳도 줄고 있습니다.","⑤ 지금까지 짱뚱어의 생김새와 먹이, 사는 곳을 알아보았습니다.","들어 주셔서 고맙습니다."],"title":"짱뚱어를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#18','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C12',3,'mc','auto','「우리 반 텃밭 채소」를 발표할 때 조사 항목을 바르게 모은 것은 무엇인가요?',ARRAY['K4-1-u5-X12']::text[],false,'{"seq":18,"concept":"K4-1-u5-C12","difficulty":3,"kind":"mc","stem":"「우리 반 텃밭 채소」를 발표할 때 조사 항목을 바르게 모은 것은 무엇인가요?","options":[{"t":"어떤 채소를 심었는지 · 어떻게 키우는지 · 언제 거두는지","correct":true},{"t":"채소 이름의 글자 수 · 내가 좋아하는 색","mis":"K4-1-u5-X12"},{"t":"텃밭 울타리의 못 개수","mis":"K4-1-u5-X12"},{"t":"채소 씨앗을 산 가게 이름","mis":"K4-1-u5-X12"}],"explanation":["채소를 소개하려면","심기 · 키우기 · 거두기","주제와 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#19','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C26',3,'mc','auto','읽은 까닭을 가장 잘 쓴 문장은 무엇인가요?',ARRAY['K4-1-u5-X26','K4-1-u5-X35']::text[],false,'{"seq":19,"concept":"K4-1-u5-C26","difficulty":3,"kind":"mc","stem":"읽은 까닭을 가장 잘 쓴 문장은 무엇인가요?","options":[{"t":"천둥을 무서워하는 동생과 함께 읽으려고 천둥이 나오는 이 책을 골랐다.","correct":true},{"t":"이 책은 모두 백 쪽이다.","mis":"K4-1-u5-X26"},{"t":"책을 다 읽는 데 한 시간이 걸렸다.","mis":"K4-1-u5-X26"},{"t":"주인공은 끝내 천둥을 무서워하지 않게 된다.","mis":"K4-1-u5-X35"}],"explanation":["왜 골랐나요?","계기","읽은 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#20','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C36',3,'mc','auto','「빨간 장화 한 짝」 감상문을 처음 · 가운데 · 끝 세 문단으로 나눌 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X36']::text[],false,'{"seq":20,"concept":"K4-1-u5-C36","difficulty":3,"kind":"mc","stem":"「빨간 장화 한 짝」 감상문을 처음 · 가운데 · 끝 세 문단으로 나눌 때 알맞은 것은 무엇인가요?","options":[{"t":"① / ②~⑤ / ⑥","correct":true},{"t":"①② / ③④ / ⑤⑥","mis":"K4-1-u5-X36"},{"t":"①~③ / ④ / ⑤⑥","mis":"K4-1-u5-X36"},{"t":"나누지 않고 한 문단","mis":"K4-1-u5-X36"}],"explanation":["처음은 까닭","가운데는 내용과 장면","끝은 느낌"],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#21','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C44',3,'mc','auto','「발표는 잘하는 친구에게만 맡기자.」에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u5-X43','K4-1-u5-X02','K4-1-u5-X19']::text[],false,'{"seq":21,"concept":"K4-1-u5-C44","difficulty":3,"kind":"mc","stem":"「발표는 잘하는 친구에게만 맡기자.」에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"누구나 준비하고 연습하면 자신 있게 말할 수 있으니 모두 해 보아야 한다","correct":true},{"t":"잘하는 친구만 하면 된다","mis":"K4-1-u5-X43"},{"t":"발표는 아무도 안 해도 된다","mis":"K4-1-u5-X02"},{"t":"잘 못하는 친구는 듣지 않아도 된다","mis":"K4-1-u5-X19"}],"explanation":["하람이를 떠올려요.","준비와 연습","모두 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#22','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C46',3,'mc','auto','이 단원에서 배운 것을 바르게 정리한 것을 고르세요.',ARRAY['K4-1-u5-X49','K4-1-u5-X23']::text[],false,'{"seq":22,"concept":"K4-1-u5-C46","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 것을 바르게 정리한 것을 고르세요.","options":[{"t":"말로는 자신 있게 발표하고 글로는 감상문을 써서 생각을 전하며, 다른 사람의 생각에도 귀 기울인다","correct":true},{"t":"말로 전하기만 중요하다","mis":"K4-1-u5-X49"},{"t":"내 생각만 전하면 된다","mis":"K4-1-u5-X49"},{"t":"감상문은 혼자 간직하는 글이라 나누지 않는다","mis":"K4-1-u5-X23"}],"explanation":["말로","글로","귀 기울이기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#23','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C14',4,'essay','teacher','발표 자료를 찾을 때 믿을 만한 자료인지 알아보는 방법을 쓰고, 자료를 쓸 때 함께 해야 할 일을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u5-C14","difficulty":4,"kind":"essay","stem":"발표 자료를 찾을 때 믿을 만한 자료인지 알아보는 방법을 쓰고, 자료를 쓸 때 함께 해야 할 일을 쓰세요.","answer_guide":{"answer":"예: 누가 만들었는지 분명한 곳의 자료인지 살피고, 출처를 알 수 없는 댓글이나 들은 이야기는 다른 믿을 만한 자료에서 확인한다. 자료를 쓸 때는 어디서 가져왔는지 출처를 밝힌다.","scoring_points":["누가 만들었는지 살핀다고 썼는가","출처 모를 내용은 확인한다고 썼는가","출처를 밝힌다고 썼는가"]},"explanation":["누가 만들었나요?","확인","출처"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#24','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C25',4,'essay','teacher','「빨간 장화 한 짝」 감상문에 어울리는 제목을 지어 쓰고, 그렇게 지은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u5-C25","difficulty":4,"kind":"essay","stem":"「빨간 장화 한 짝」 감상문에 어울리는 제목을 지어 쓰고, 그렇게 지은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「얼굴도 모르는 사이의 친절」 — 글쓴이가 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했다고 했으니, 그 느낌이 드러나게 지었다.","scoring_points":["책 제목을 그대로 옮기지 않고 지었는가","감상문의 생각이나 느낌이 드러나는가","까닭을 썼는가"]},"explanation":["글쓴이가 느낀 것","⑤를 봐요.","드러나게"],"asset":{"type":"passage","lines":["① 빨간 장화 그림이 궁금해서 학급 문고에서 이 책을 꺼냈다.","② 리아는 비 온 뒤 놀이터에서 빨간 장화 한 짝을 줍는다.","③ 리아는 주인을 찾으려고 놀이터 기둥에 쪽지를 붙인다.","④ 사흘 뒤 쪽지 아래에 고맙다는 글씨가 적혀 있는 장면이 가장 기억에 남았다.","⑤ 얼굴도 모르는 사람끼리 마음이 오간 것이 따뜻했기 때문이다.","⑥ 나도 주운 물건이 있으면 주인을 찾아 주려고 애써야겠다."],"title":"「빨간 장화 한 짝」을 읽고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u5_review_d#25','kor',4,1,'u5','','g4_1_kor_u5_review_d','unit_review','K4-1-u5-C44',4,'essay','teacher','이 단원에서 배운 것 가운데 앞으로 꾸준히 실천하고 싶은 일 두 가지를 말로 전하기와 글로 전하기에서 하나씩 골라 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u5-C44","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 것 가운데 앞으로 꾸준히 실천하고 싶은 일 두 가지를 말로 전하기와 글로 전하기에서 하나씩 골라 쓰세요.","answer_guide":{"answer":"예: 말로는 다음 모둠 발표에서 자료의 출처를 밝히고 어려운 말을 쉬운 말로 바꾸어 말하겠다. 글로는 한 달에 한 권씩 독서 감상문을 써서 친구들과 댓글로 감상을 나누겠다.","scoring_points":["말로 전하기 실천을 썼는가","글로 전하기 실천을 썼는가","배운 방법이 드러나게 썼는가"]},"explanation":["말로","글로","꾸준히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
